except Exception:
    class _SpacesShim:
        def GPU(self, fn=None, **kwargs):
            del kwargs

            def decorator(inner):
                return inner

            return decorator(fn) if fn else decorator

    spaces = _SpacesShim()


from arena.api import app as fastapi_app
from arena.api import service
from arena.gradio_app import RunOutputs, build_app, create_run_gpu as _create_run_gpu


@spaces.GPU(duration=120)
