def server_config() -> dict[str, int | str]:
    host = os.getenv("GRADIO_SERVER_NAME", os.getenv("HOST", "0.0.0.0"))
    port = int(os.getenv("GRADIO_SERVER_PORT") or os.getenv("PORT") or "7860")
    return {"host": host, "port": port}


