# ── State helpers ─────────────────────────────────────────────────────────────

def _post(url: str, payload: dict, timeout: int = 120):
    """POST to Modal endpoint, return JSON or raise."""
    resp = requests.post(url, json=payload, timeout=timeout)
    resp.raise_for_status()
    data = resp.json()
    if isinstance(data, dict) and data.get("error"):
        raise RuntimeError(data["error"])
    return data


def ensure_session(state: dict):
    """Create per-browser catalog state lazily."""
    state = state or {}
    state.setdefault("session_id", str(uuid.uuid4()))
    state.setdefault("catalog_loaded", False)
    state.setdefault("history", [])
    return state


def render_schema_preview(columns, sample_df=None, row_count=None):
    count_text = f"{row_count:,} rows" if isinstance(row_count, int) else "Catalog preview"
    schema_rows = ""

    for column in columns:
        sample = ""
        dtype = ""
        if sample_df is not None and column in sample_df.columns:
            dtype = str(sample_df[column].dtype)
            non_empty = sample_df[column].dropna()
            sample = "" if non_empty.empty else str(non_empty.iloc[0])
        schema_rows += (
            "<tr>"
            f"<td><b>{html.escape(str(column))}</b></td>"
            f"<td>{html.escape(dtype)}</td>"
            f"<td>{html.escape(sample)}</td>"
            "</tr>"
        )

    return f"""
    <p style='color:#6B6456;font-size:0.7rem;margin-bottom:6px'>{count_text} · {len(columns)} columns</p>
    <table class='schema-table'>
      <thead><tr><th>Column</th><th>Type</th><th>Sample</th></tr></thead>
      <tbody>{schema_rows}</tbody>
    </table>
    """


def render_sources(sources):
    if not sources:
        return "<p style='color:#2A2A2A;font-size:0.72rem'>Matched products will appear here after a reply.</p>"

    rows = ""
    for source in sources[:3]:
        cells = "".join(
            f"<td>{html.escape(str(value))}</td>"
            for value in source.values()
        )
        rows += f"<tr>{cells}</tr>"

    headers = "".join(
        f"<th>{html.escape(str(key))}</th>"
        for key in sources[0].keys()
    )
    return f"""
    <table class='schema-table'>
      <thead><tr>{headers}</tr></thead>
      <tbody>{rows}</tbody>
    </table>
    """


# ── Catalog upload & index build ─────────────────────────────────────────────

def handle_upload(csv_file, state: dict):
    """
    Called when user uploads a CSV.
    1. Reads first 5 rows for schema preview.
    2. Sends full CSV to Modal /build_index.
    3. Stores session token in state.
    Returns: schema_html, status_msg, updated_state
    """
    state = ensure_session(state)

    if csv_file is None:
        return "<p style='color:#6B6456'>No file uploaded.</p>", "⬤ No catalog loaded", state

    try:
        with open(csv_file.name, "rb") as f:
            csv_bytes = f.read()
        catalog_csv = csv_bytes.decode("utf-8-sig")
    except Exception as e:
        return f"<p style='color:#E05A5A'>CSV read error: {e}</p>", "⬤ Error", state

    try:
        preview_df = pd.read_csv(io.StringIO(catalog_csv), nrows=3)
        preview_columns = list(preview_df.columns)
        schema_html = render_schema_preview(preview_columns, preview_df)
    except Exception as e:
        return f"<p style='color:#E05A5A'>CSV parse error: {e}</p>", "⬤ Error", state

    # Send to Modal
    if not BUILD_INDEX_URL:
        status = "⚠ MODAL_BUILD_INDEX_URL not set — running in demo mode"
        state["catalog_loaded"] = True
        state["catalog_name"] = os.path.basename(csv_file.name)
        state["history"] = []
        state["demo_df"] = pd.read_csv(io.StringIO(catalog_csv)).to_dict(orient="records")
        return schema_html, status, state

    try:
        result = _post(
            BUILD_INDEX_URL,
            {
                "catalog_csv": catalog_csv,
                "session_id": state["session_id"],
            },
        )
        state["session_id"] = result.get("session_id", state["session_id"])
        state["catalog_loaded"] = True
        state["history"] = []
        state["catalog_name"] = os.path.basename(csv_file.name)
        row_count = result.get("row_count")
        columns = result.get("columns") or preview_columns
        schema_html = render_schema_preview(columns, preview_df, row_count)
        product_label = f"{row_count:,} products" if isinstance(row_count, int) else "products"
        status = f"✓ Catalog loaded: {product_label}"
    except Exception as e:
        state["catalog_loaded"] = False
        status = f"⚠ Index error: {e}"

    return schema_html, status, state


# ── Voice transcription ───────────────────────────────────────────────────────

def transcribe_audio(audio_path, state: dict):
    """Send audio file to Modal Whisper endpoint, return transcript."""
    state = ensure_session(state)

    if audio_path is None:
        return "", state

    if not TRANSCRIBE_URL:
        return "[Voice transcription requires MODAL_TRANSCRIBE_URL]", state

    try:
        audio_b64 = base64.b64encode(open(audio_path, "rb").read()).decode()
        result = _post(TRANSCRIBE_URL, {"audio_b64": audio_b64, "language": "en"}, timeout=120)
        return result.get("text", ""), state
    except Exception as e:
        return f"[Transcription error: {e}]", state


# ── Chat handler ──────────────────────────────────────────────────────────────

def chat_fn(message: str, ui_history: list, state: dict, business_name: str):
    """
    Called by gr.ChatInterface on each user message.
    Sends message + history to Modal /chat_query.
    """
    state = ensure_session(state)

    if not message.strip():
        return "", state, []

    if not state.get("catalog_loaded"):
        return (
            "**No catalog loaded.** Upload a CSV file in the sidebar first, "
            "then ask me anything about your products."
        ), state, []

    if not CHAT_QUERY_URL:
        # Demo mode — simple keyword match against in-memory df
        df_records = state.get("demo_df", [])
        matches = [
            r for r in df_records
            if any(message.lower() in str(v).lower() for v in r.values())
        ][:3]
        if matches:
            lines = "\n".join(f"• {r}" for r in matches)
            reply = f"_(Demo mode — no Modal endpoint)_\n\nTop matches:\n{lines}"
            state["history"].extend([
                {"role": "user", "content": message},
                {"role": "assistant", "content": reply},
            ])
            return reply, state, matches
        reply = "_(Demo mode)_ No matching products found for that query."
        state["history"].extend([
            {"role": "user", "content": message},
            {"role": "assistant", "content": reply},
        ])
        return reply, state, []

    payload = {
        "message": message,
        "session_id": state["session_id"],
        "history": state.get("history", [])[-6:],
        "business_name": (business_name or "").strip() or "our store",
    }

    try:
        result = _post(CHAT_QUERY_URL, payload, timeout=180)
        reply = result.get("reply", "No response from model.")
        state["history"].extend([
            {"role": "user", "content": message},
            {"role": "assistant", "content": reply},
        ])
        return reply, state, result.get("sources", [])
    except requests.exceptions.Timeout:
        return "⏱ The model took too long to respond. Please try again.", state, []
    except Exception as e:
        return f"⚠ Backend error: {e}", state, []


# ── Embed code generator ──────────────────────────────────────────────────────

def generate_embed(space_id: str):
    """Return iframe embed snippet for a HF Space."""
    space_id = space_id.strip()
    if not space_id:
        return "<p style='color:#6B6456;font-size:0.72rem'>Enter your HF Space ID above.</p>"

    snippet = f'<iframe\n  src="https://huggingface.co/spaces/{space_id}"\n  width="100%"\n  height="600"\n  frameborder="0"\n  allow="microphone"\n></iframe>'
    return f"<div class='embed-code'>{snippet}</div>"


# ── Gradio UI ─────────────────────────────────────────────────────────────────

def build_ui():
    with gr.Blocks(
        title="CatalogChat — AI Product Assistant",
    ) as demo:
        session_state = gr.State({})

        # ── Title bar ──
        gr.HTML("""
        <div id="app-title">
          <div>
            <h1>⬡ CatalogChat</h1>
            <div class="subtitle">Backyard AI · Qwen2.5-7B · BM25 Retrieval</div>
          </div>
          <span class="badge">OFF-BRAND</span>
          <span class="badge">OFF THE GRID</span>
        </div>
        """)

        with gr.Row(equal_height=True):

            # ── LEFT SIDEBAR ──────────────────────────────────────────────────
            with gr.Column(scale=1, elem_id="sidebar", min_width=280):

                gr.HTML("<div style='color:#F5A623;font-size:0.7rem;letter-spacing:0.15em;font-weight:700;margin-bottom:12px'>▸ CATALOG</div>")

                csv_upload = gr.File(
                    label="Upload product CSV",
                    file_types=[".csv"],
                    elem_classes=["upload-zone"],
                )

                upload_btn = gr.Button("⟳ Index Catalog", variant="primary", size="sm")

                catalog_status = gr.HTML(
                    "<span class='status-dot'></span> <span style='color:#6B6456;font-size:0.72rem'>No catalog loaded</span>"
                )

                schema_display = gr.HTML(
                    "<p style='color:#2A2A2A;font-size:0.72rem;margin-top:8px'>Schema preview will appear here.</p>"
                )

                business_name = gr.Textbox(
                    placeholder="Business name",
                    label="Business name",
                    value="our store",
                    lines=1,
                )

                gr.HTML("<hr style='border:none;border-top:1px solid #1E1E1E;margin:16px 0'>")

                # ── Voice input ──
                gr.HTML("<div style='color:#F5A623;font-size:0.7rem;letter-spacing:0.15em;font-weight:700;margin-bottom:8px'>▸ VOICE INPUT</div>")

                audio_input = gr.Audio(
                    sources=["microphone"],
                    type="filepath",
                    label="Record your question",
                    show_label=False,
                )

                transcript_box = gr.Textbox(
                    placeholder="Transcript appears here — edit then send",
                    label="Transcript",
                    lines=2,
                    show_label=False,
                )

                transcribe_btn = gr.Button("⟳ Transcribe", variant="secondary", size="sm")

                gr.HTML("<hr style='border:none;border-top:1px solid #1E1E1E;margin:16px 0'>")

                # ── Embed generator ──
                with gr.Accordion("⟐ Embed Code Generator", open=False):
                    gr.HTML("<p style='color:#6B6456;font-size:0.7rem;margin-bottom:8px'>Generate iframe snippet for your website</p>")
                    space_id_input = gr.Textbox(
                        placeholder="your-username/your-space",
                        label="HF Space ID",
                        show_label=False,
                    )
                    embed_btn = gr.Button("Generate Snippet", variant="secondary", size="sm")
                    embed_output = gr.HTML()

                gr.HTML("<hr style='border:none;border-top:1px solid #1E1E1E;margin:16px 0'>")

                # ── Starter prompts ──
                gr.HTML("<div style='color:#F5A623;font-size:0.7rem;letter-spacing:0.15em;font-weight:700;margin-bottom:8px'>▸ TRY ASKING</div>")
                gr.HTML("""
                <div style='display:flex;flex-direction:column;gap:6px'>
                  <div style='background:#111;border:1px solid #1E1E1E;padding:6px 10px;border-radius:3px;font-size:0.72rem;color:#9A8F80;cursor:pointer'
                       onclick="document.querySelector('#chat-input textarea').value=this.textContent">
                    What products do you have under ₦8,000?
                  </div>
                  <div style='background:#111;border:1px solid #1E1E1E;padding:6px 10px;border-radius:3px;font-size:0.72rem;color:#9A8F80;cursor:pointer'
                       onclick="document.querySelector('#chat-input textarea').value=this.textContent">
                    Show me blue dresses in medium
                  </div>
                  <div style='background:#111;border:1px solid #1E1E1E;padding:6px 10px;border-radius:3px;font-size:0.72rem;color:#9A8F80;cursor:pointer'
                       onclick="document.querySelector('#chat-input textarea').value=this.textContent">
                    Compare your top 3 sofas
                  </div>
                </div>
                """)

            # ── CHAT PANEL ────────────────────────────────────────────────────
            with gr.Column(scale=3):

                chatbot = gr.Chatbot(
                    label="",
                    # type="messages",
                    height=520,
                    show_label=False,
                    # bubble_full_width=False,
                    avatar_images=(
                        None,  # user avatar
                        "https://api.dicebear.com/7.x/bottts-neutral/svg?seed=catalogchat&backgroundColor=0D0D0D",
                    ),
                    render_markdown=True,
                )

                with gr.Row():
                    chat_input = gr.Textbox(
                        placeholder="Ask about products, prices, availability…",
                        show_label=False,
                        lines=1,
                        scale=5,
                        elem_id="chat-input",
                        container=False,
                    )
                    send_btn = gr.Button("Send ↵", variant="primary", scale=1)

                gr.HTML("""
                <div style='text-align:center;margin-top:8px;color:#2A2A2A;font-size:0.65rem;letter-spacing:0.1em'>
                  POWERED BY QWEN2.5-7B · MODAL SERVERLESS · BM25 RETRIEVAL
                </div>
                """)

                with gr.Accordion("Matched Products", open=False):
                    sources_display = gr.HTML(
                        "<p style='color:#2A2A2A;font-size:0.72rem'>Matched products will appear here after a reply.</p>"
                    )

        # ── Wire events ───────────────────────────────────────────────────────

        # Upload & index
        upload_btn.click(
            fn=handle_upload,
            inputs=[csv_upload, session_state],
            outputs=[schema_display, catalog_status, session_state],
        )

        # Also trigger on file drop
        csv_upload.change(
            fn=handle_upload,
            inputs=[csv_upload, session_state],
            outputs=[schema_display, catalog_status, session_state],
        )

        # Chat — send button
        def respond(message, history, state, business):
            history = history or []
            answer, state, sources = chat_fn(message, history, state, business)
            if message.strip():
                history.extend([
                    {"role": "user", "content": message},
                    {"role": "assistant", "content": answer},
                ])
            return "", history, state, render_sources(sources)

        send_btn.click(
            fn=respond,
            inputs=[chat_input, chatbot, session_state, business_name],
            outputs=[chat_input, chatbot, session_state, sources_display],
        )

        # Chat — Enter key
        chat_input.submit(
            fn=respond,
            inputs=[chat_input, chatbot, session_state, business_name],
            outputs=[chat_input, chatbot, session_state, sources_display],
        )

        # Voice transcription
        transcribe_btn.click(
            fn=transcribe_audio,
            inputs=[audio_input, session_state],
            outputs=[transcript_box, session_state],
        )

        # Send transcript as chat message
        transcript_box.submit(
            fn=respond,
            inputs=[transcript_box, chatbot, session_state, business_name],
            outputs=[transcript_box, chatbot, session_state, sources_display],
        )

        # Embed generator
        embed_btn.click(
            fn=generate_embed,
            inputs=[space_id_input],
            outputs=[embed_output],
        )

    return demo


# ── Entry point ───────────────────────────────────────────────────────────────
if __name__ == "__main__":
    demo = build_ui()
    demo.launch(
        css=CUSTOM_CSS,
        theme=gr.themes.Base(
            primary_hue="orange",
            neutral_hue="stone",
            font=gr.themes.GoogleFont("JetBrains Mono"),
        ),
        # server_name="0.0.0.0",
        # server_port=3000,
        share=False,
    )

