        yield to_chatbot(state["log"]), state, gr.update(value="")
        return

    if not state.get("started"):
        state["log"].append(
            {
                "role": "assistant",
                "content": "The room blinks at you. Press **Start Session** first.",
            }
        )
        yield to_chatbot(state["log"]), state, gr.update(value="")
        return

    state["turn"] += 1
    state["log"].append({"role": "user", "content": user_text})

    # Show the user line immediately.
    yield to_chatbot(state["log"]), state, gr.update(value="")

    for persona in PERSONAS:
        typing_text = f"{persona['emoji']} **{persona['name']}** is typing…"
        state["log"].append({"role": "assistant", "content": typing_text})
        yield to_chatbot(state["log"]), state, gr.update(value="")

        time.sleep(random.uniform(0.35, 1.1))

        # Generate only during GPU time.
        reply = generate_persona_reply(persona, state["log"][:-1])

        state["log"][-1] = {
            "role": "assistant",
            "content": f"**{persona['name']}** {persona['emoji']}\n\n{reply}",
        }

        yield to_chatbot(state["log"]), state, gr.update(value="")

        time.sleep(random.uniform(0.12, 0.35))

    # Tiny epilogue beat.
    state["log"].append(
        {
            "role": "assistant",
            "content": "The room rustles. Someone whispers: *again?*",
        }
    )
    yield to_chatbot(state["log"]), state, gr.update(value="")


with gr.Blocks(css=CSS, head=HEAD, title="Council of Tiny Minds") as demo:
