# ── Custom route registration ─────────────────────────────────────────────────

def _register_custom_routes(fastapi_app):
    try:
        fastapi_app.mount(
            "/static", StaticFiles(directory=str(STATIC)), name="museum_static"
        )
    except Exception as e:
        print(f"[routes] /static mount skipped: {e}")

    @fastapi_app.get("/museum")
    async def museum():
        return FileResponse(str(STATIC / "index.html"))

    @fastapi_app.get("/galeria")
    async def galeria():
        return FileResponse(str(STATIC / "galeria.html"))

    @fastapi_app.post("/generate")
    async def generate_endpoint(request: Request):
        body        = await request.json()
        sketch_b64  = body.get("sketch_b64", "")
        description = body.get("description", "").strip()
        strength    = float(body.get("strength", 0.7))
        if not sketch_b64 or not description:
            return JSONResponse({"ok": False, "error": "Sketch and description are required"})
        try:
            image_b64 = inference_module.generate(sketch_b64, description, strength)
            return JSONResponse({"ok": True, "image": image_b64})
        except Exception as e:
            return JSONResponse({"ok": False, "error": str(e)})

    @fastapi_app.post("/gallery/public")
    async def public_gallery(request: Request):
        body   = await request.json()
        dreams = gallery_module.get_public_dreams(
            body.get("limit", 50), body.get("offset", 0)
        )
        return JSONResponse({"ok": True, "dreams": dreams})

    @fastapi_app.post("/gallery/user")
    async def user_gallery(request: Request):
        body    = await request.json()
        user_id = body.get("user_id", "")
        if not user_id:
            return JSONResponse({"ok": False, "error": "user_id required"})
        return JSONResponse({"ok": True, "dreams": gallery_module.get_user_dreams(user_id)})

    @fastapi_app.post("/gallery/save")
    async def save_dream_endpoint(request: Request):
        body    = await request.json()
        user_id = body.get("user_id", "")
        if not user_id:
            return JSONResponse({"ok": False, "error": "Login required to save dreams"})
        result = gallery_module.save_dream(
            user_id,
            body.get("sketch_b64", ""),
            body.get("image_b64", ""),
            body.get("description", ""),
            body.get("visibility", "public"),
        )
        return JSONResponse(result)

    @fastapi_app.post("/gallery/delete")
    async def delete_dream_endpoint(request: Request):
        body   = await request.json()
        result = gallery_module.delete_dream(
            body.get("dream_id", ""), body.get("user_id", "")
        )
        return JSONResponse(result)

    @fastapi_app.post("/gallery/toggle")
    async def toggle_visibility_endpoint(request: Request):
        body   = await request.json()
        result = gallery_module.toggle_visibility(
            body.get("dream_id", ""), body.get("user_id", "")
        )
        return JSONResponse(result)

    print("[routes] custom routes registered")


def _attach_routes_with_priority(fastapi_app):
    """Register custom routes, then move them to the front of the router so
    they take precedence over Gradio's own catch-all frontend routes."""
    n_before = len(fastapi_app.router.routes)
    _register_custom_routes(fastapi_app)
    new_routes = fastapi_app.router.routes[n_before:]
    del fastapi_app.router.routes[n_before:]
    fastapi_app.router.routes[0:0] = new_routes


# ── Entry point ───────────────────────────────────────────────────────────────
# demo.launch() is required for ZeroGPU (@spaces.GPU) to register correctly.
# prevent_thread_lock=True returns the real FastAPI app uvicorn is serving, so
# we can attach the museum routes to the exact object that handles requests.
# ssr_mode=False prevents Gradio 6.x from starting a Node.js SSR proxy.

if __name__ == "__main__":
    app, _local_url, _share_url = demo.launch(
        server_name="0.0.0.0",
        server_port=7860,
        ssr_mode=False,
        prevent_thread_lock=True,
    )

    _attach_routes_with_priority(app)

    demo.block_thread()

