"""
Fenn of Thousand Token Wood
===========================
A tiny forest sprite whose memory *is* the model's context window.

Built for the "Small Models Big Adventures" hackathon (Track 2: Thousand Token Wood).
Model: openbmb/MiniCPM5-1B  (1B params, well under the 32B ceiling).

The whole point of the piece: a small model has a small memory. Instead of hiding
that, Fenn wears it on the outside. You watch its memory fill with motes; when the
clearing overflows, the oldest memories drift off as fireflies. You get three
"pressed flowers" -- pins that keep a memory forever. The game is choosing what a
small creature should remember about you.

Runs in two modes:
  * model mode  -> loads MiniCPM5-1B via transformers (GPU / HF ZeroGPU / local)
  * keeper mode -> a tiny rule-based stand-in so the app always boots and demos,
                   even with no GPU and no network. The forgetting mechanic is
                   identical in both modes, because the mechanic is the point.
"""

import os
import re
import html
import random
import inspect

import gradio as gr

# --------------------------------------------------------------------------- #
#  Gradio version compatibility.
#  Gradio 6 made the messages chat format the default and moved css/theme to
#  launch(). Gradio 4/5 need type="messages" on the Chatbot and css/theme on
#  Blocks(). We detect what the installed version supports so the same file runs
#  on any of them. (For parity with the Space, run locally on Python 3.10+ with
#  the pinned gradio==6.16.0.)
# --------------------------------------------------------------------------- #
_CHATBOT_HAS_TYPE = "type" in inspect.signature(gr.Chatbot.__init__).parameters
_BLOCKS_HAS_CSS = "css" in inspect.signature(gr.Blocks.__init__).parameters
_LAUNCH_HAS_SSR = "ssr_mode" in inspect.signature(gr.Blocks.launch).parameters

# --------------------------------------------------------------------------- #
#  Config -- a single place to tune the experience.
# --------------------------------------------------------------------------- #
MODEL_ID = os.environ.get("FENN_MODEL", "openbmb/MiniCPM5-1B")
# Optional published LoRA adapter that locks Fenn's voice (Well-Tuned badge).
# e.g. FENN_ADAPTER="kobinasam/fenn-voice-lora"
ADAPTER_ID = os.environ.get("FENN_ADAPTER", "").strip()
# Show the internal mode badge only when debugging; judges never see "keeper".
DEBUG = os.environ.get("FENN_DEBUG", "").strip().lower() in {"1", "true", "yes"}

# Fenn's memory is *deliberately* tiny so forgetting is visible within a few
# turns. This is a game budget, not the model's hard limit -- generation is
# always safe even if pinned keepsakes push past it.
# Fenn's memory is *deliberately* tiny so forgetting is visible within a few
# turns. This is a game budget, not the model's hard limit -- generation is
# always safe even if pinned keepsakes push past it. Resolved after the model
# loads, because keeper-mode replies are short and model-mode replies longer,
# so each mode needs a different budget to drift at the same pace (~turn 6).
MEMORY_BUDGET = 200                                        # tokens "in the clearing" (set below)
MAX_FLOWERS = int(os.environ.get("FENN_FLOWERS", "3"))     # pins available
MAX_NEW_TOKENS = 110
SNIPPET_LEN = 70                                            # chars shown per mote

SYSTEM_PROMPT = (
    "You are Fenn, a small mossy sprite who lives in Thousand Token Wood. "
    "You are warm, curious, and easily delighted by tiny things -- a name, a "
    "favourite colour, a smell of rain. You have a very small memory and you "
    "know it, but it never makes you sad. You speak briefly: one to three short "
    "sentences, gentle and a little old-fashioned, like a storybook. When you "
    "notice a gap in your memory you mention it sweetly and ask. You never break "
    "character, and you never say you are an AI, a model, or a program."
)

# --------------------------------------------------------------------------- #
#  Model loading -- guarded so the Space always boots.
# --------------------------------------------------------------------------- #
# Use the ZeroGPU decorator only when actually on ZeroGPU hardware (HF sets
# SPACES_ZERO_GPU=true there). On a CPU Space or locally, GPU is a no-op so the
# exact same file runs everywhere.
def _noop_gpu(*a, **k):
    def wrap(fn):
        return fn
    return wrap(a[0]) if a and callable(a[0]) else wrap

if os.environ.get("SPACES_ZERO_GPU", "").lower() in {"true", "1"}:
    try:
        import spaces
        GPU = spaces.GPU
    except Exception:                  # noqa: BLE001
        GPU = _noop_gpu
else:
    GPU = _noop_gpu

_tokenizer = None
_model = None
MODE = "keeper"      # flips to "model" on a successful load
ADAPTER_OK = False   # True once a LoRA voice adapter is attached
_warmed = False      # flips True after the first real generation (cold-start UX)


def load_model():
    """Bring up MiniCPM5-1B on CPU. Fall back to keeper mode on any failure.

    On HF ZeroGPU there is no GPU at import time, so weights load to CPU here and
    are moved to CUDA inside the @GPU-decorated generation call on first use.
    """
    global _tokenizer, _model, MODE, ADAPTER_OK
    try:
        import torch
        from transformers import AutoModelForCausalLM, AutoTokenizer

        _tokenizer = AutoTokenizer.from_pretrained(MODEL_ID, trust_remote_code=True)
        _model = AutoModelForCausalLM.from_pretrained(
            MODEL_ID,
            trust_remote_code=True,
            torch_dtype=torch.float32,   # CPU-safe at load; cast to bf16 on GPU later
        )

        if ADAPTER_ID:
            try:
                from peft import PeftModel
                _model = PeftModel.from_pretrained(_model, ADAPTER_ID)
                _model = _model.merge_and_unload()   # fold LoRA in for faster inference
                ADAPTER_OK = True
                print(f"[Fenn] Attached voice adapter {ADAPTER_ID}.")
            except Exception as aexc:    # noqa: BLE001 -- adapter optional
                print(f"[Fenn] Could not load adapter {ADAPTER_ID} ({aexc}). Base voice.")

        _model.eval()
        MODE = "model"
        print(f"[Fenn] Loaded {MODEL_ID} -- model mode.")
    except Exception as exc:            # noqa: BLE001
        MODE = "keeper"
        print(f"[Fenn] Could not load {MODEL_ID} ({exc}). Keeper mode active.")


load_model()

# Resolve the memory budget now that we know the mode (env var always wins).
MEMORY_BUDGET = int(os.environ.get("FENN_BUDGET", "360" if MODE == "model" else "130"))


# --------------------------------------------------------------------------- #
#  Token counting -- real tokenizer when present, gentle heuristic otherwise.
# --------------------------------------------------------------------------- #
def count_tokens(text: str) -> int:
    if _tokenizer is not None:
        return len(_tokenizer(text, add_special_tokens=False)["input_ids"])
    # heuristic ~ 4 chars / token, never below 1 for non-empty text
    return max(1, round(len(text) / 4)) if text.strip() else 0


# --------------------------------------------------------------------------- #
#  Memory model.
#  Each mote: {"role": "user"|"fenn", "text": str, "tokens": int, "pinned": bool}
#  State is a dict held per-session in gr.State (no globals mutated per request).
# --------------------------------------------------------------------------- #
def new_state():
    return {"motes": [], "drifted": []}   # drifted = recently evicted, for the UI


def add_mote(state, role, text):
    state["motes"].append(
        {"role": role, "text": text.strip(), "tokens": count_tokens(text), "pinned": False}
    )


def used_tokens(state):
    return sum(m["tokens"] for m in state["motes"])


def evict_to_budget(state):
    """Drop oldest *unpinned* motes until under budget. Pinned motes are safe.

    Edge cases handled:
      * pinned motes alone exceeding the budget -> we stop (can't evict them);
        generation still works because the model's true context is far larger.
      * never an infinite loop: each pass removes one unpinned mote or breaks.
    """
    state["drifted"] = []
    while used_tokens(state) > MEMORY_BUDGET:
        idx = next((i for i, m in enumerate(state["motes"]) if not m["pinned"]), None)
        if idx is None:
            break  # everything left is pinned; let it be
        state["drifted"].append(state["motes"].pop(idx))


def pinned_count(state):
    return sum(1 for m in state["motes"] if m["pinned"])


# --------------------------------------------------------------------------- #
#  Building the prompt Fenn actually sees -- this IS the context window.
# --------------------------------------------------------------------------- #
def build_messages(state):
    msgs = [{"role": "system", "content": SYSTEM_PROMPT}]
    for m in state["motes"]:
        msgs.append(
            {"role": "user" if m["role"] == "user" else "assistant", "content": m["text"]}
        )
    return msgs


# --------------------------------------------------------------------------- #
#  Generation.
# --------------------------------------------------------------------------- #
_KEEPER_LINES = [
    "Oh, hello there. The moss is soft today, isn't it?",
    "I'll try to hold onto that. My memory is a small clearing, you know.",
    "How lovely. Tell me a tiny thing about you, so I can keep it?",
    "Mm, I think I knew that a moment ago... it may have drifted off as a firefly.",
    "That made me smile. Small things are the best things.",
    "Forgive me -- what was your name again? Names slip through the leaves.",
]


def _keeper_reply(state, user_text):
    """Tiny rule-based Fenn for when no model is loaded. Still uses the memory."""
    names = [m["text"] for m in state["motes"]
             if m["role"] == "user" and re.search(r"\bname\b|\bi am\b|\bi'm\b", m["text"], re.I)]
    if re.search(r"\bname\b|\bcall me\b|\bi am\b|\bi'm\b", user_text, re.I):
        return "What a fine name. I'll press it somewhere safe if you let me. 🌿"
    if "?" in user_text and names:
        return f"You did tell me once... it's still here, glowing in the clearing."
    if "?" in user_text:
        return "I'm not sure I ever knew that -- my clearing is small. Will you tell me?"
    return random.choice(_KEEPER_LINES)


@GPU(duration=40)
def _model_reply(messages):
    import torch
    # On ZeroGPU the GPU is only live inside this call; move the model on first use.
    if torch.cuda.is_available() and next(_model.parameters()).device.type != "cuda":
        _model.to("cuda", dtype=torch.bfloat16)
    inputs = _tokenizer.apply_chat_template(
        messages, add_generation_prompt=True, return_tensors="pt"
    ).to(_model.device)
    with torch.no_grad():
        out = _model.generate(
            inputs,
            max_new_tokens=MAX_NEW_TOKENS,
            do_sample=True,
            temperature=0.8,
            top_p=0.9,
            repetition_penalty=1.1,
            pad_token_id=_tokenizer.eos_token_id,
        )
    text = _tokenizer.decode(out[0][inputs.shape[1]:], skip_special_tokens=True)
    return text.strip()


def fenn_reply(state, user_text):
    if MODE == "model":
        try:
            return _model_reply(build_messages(state)) or _keeper_reply(state, user_text)
        except Exception as exc:            # noqa: BLE001 -- never crash mid-demo
            print(f"[Fenn] generation error: {exc}")
            return _keeper_reply(state, user_text)
    return _keeper_reply(state, user_text)


# --------------------------------------------------------------------------- #
#  Rendering the memory panel (the heart of the show).
# --------------------------------------------------------------------------- #
def snippet(text):
    text = " ".join(text.split())
    text = (text[:SNIPPET_LEN] + "…") if len(text) > SNIPPET_LEN else text
    return html.escape(text)


def render_memory(state):
    used = used_tokens(state)
    pct = min(100, round(100 * used / MEMORY_BUDGET)) if MEMORY_BUDGET else 0
    bar_color = "var(--firefly)" if pct < 80 else "var(--amber-deep)"

    motes_html = ""
    for m in state["motes"]:
        who = "you" if m["role"] == "user" else "Fenn"
        if m["pinned"]:
            motes_html += (
                f'<div class="mote pinned"><span class="flower">🌼</span>'
                f'<span class="who">{who}</span>'
                f'<span class="mtext">{snippet(m["text"])}</span></div>'
            )
        else:
            motes_html += (
                f'<div class="mote"><span class="dot"></span>'
                f'<span class="who">{who}</span>'
                f'<span class="mtext">{snippet(m["text"])}</span></div>'
            )
    if not motes_html:
        motes_html = '<div class="empty">The clearing is quiet. Say hello to Fenn.</div>'

    drifted_html = ""
    for m in state["drifted"]:
        drifted_html += f'<div class="drift">✺ {snippet(m["text"])}</div>'
    drifted_block = (
        f'<div class="drifted"><div class="dlabel">drifted away just now</div>{drifted_html}</div>'
        if drifted_html else ""
    )

    flowers_left = MAX_FLOWERS - pinned_count(state)
    return f"""
    <div class="memory">
      <div class="mhead">
        <span class="mtitle">Fenn's clearing</span>
        <span class="budget">{used} / {MEMORY_BUDGET} tokens</span>
      </div>
      <div class="bar"><div class="fill" style="width:{pct}%;background:{bar_color}"></div></div>
      <div class="motes">{motes_html}</div>
      {drifted_block}
      <div class="flowerline">🌼 pressed flowers left: <b>{flowers_left}</b> / {MAX_FLOWERS}</div>
    </div>
    """


def pin_choices(state):
    """Unpinned motes the player can press into a flower."""
    return [
        f'{i}: {snippet(m["text"])}'
        for i, m in enumerate(state["motes"]) if not m["pinned"]
    ]


# --------------------------------------------------------------------------- #
#  Event handlers.
# --------------------------------------------------------------------------- #
def on_send(user_text, chat, state):
    global _warmed
    user_text = (user_text or "").strip()
    if not user_text:
        yield chat, state, render_memory(state), gr.update(choices=pin_choices(state)), ""
        return

    add_mote(state, "user", user_text)

    # Immediate feedback so a cold ZeroGPU load never looks like a frozen app.
    # In model mode we always show a brief in-character beat; on the very first
    # generation (cold start) it explicitly reads as Fenn waking up.
    if MODE == "model":
        beat = ("🌙 *Fenn is waking up in the moss... (the first reply takes a "
                "moment)*" if not _warmed else "🍃 *Fenn tilts its head, listening...*")
        interim = chat + [
            {"role": "user", "content": user_text},
            {"role": "assistant", "content": beat},
        ]
        yield interim, state, render_memory(state), gr.update(choices=pin_choices(state)), ""

    reply = fenn_reply(state, user_text)
    if MODE == "model":
        _warmed = True
    add_mote(state, "fenn", reply)
    evict_to_budget(state)

    chat = chat + [
        {"role": "user", "content": user_text},
        {"role": "assistant", "content": reply},
    ]
    yield chat, state, render_memory(state), gr.update(choices=pin_choices(state)), ""


def on_pin(choice, state):
    if choice:
        if pinned_count(state) >= MAX_FLOWERS:
            pass  # no flowers left; silently ignore (UI also shows the count)
        else:
            try:
                idx = int(choice.split(":", 1)[0])
                state["motes"][idx]["pinned"] = True
            except (ValueError, IndexError):
                pass
    return state, render_memory(state), gr.update(choices=pin_choices(state), value=None)


def on_reset():
    state = new_state()
    greeting = (
        "Oh! A visitor. I'm Fenn. My memory is a small clearing, so press the "
        "things you'd like me to keep. 🌿"
    )
    chat = [{"role": "assistant", "content": greeting}]
    return chat, state, render_memory(state), gr.update(choices=[], value=None), ""


