@dataclass(frozen=True)
class DateHit:
    text: str
    sentence: str
    normalized: str | None = None


DATE_PATTERNS = [
    re.compile(
        r"\b(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|"
        r"Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Sept|Oct(?:ober)?|Nov(?:ember)?|"
        r"Dec(?:ember)?)\s+\d{1,2}(?:,\s*\d{4})?\b",
        re.IGNORECASE,
    ),
    re.compile(r"\b\d{4}-\d{2}-\d{2}\b"),
    re.compile(r"\b\d{1,2}/\d{1,2}/\d{2,4}\b"),
]

QUESTION_HINTS = {
    "parties": ["names and roles of all parties", "client contact details", "opposing party contact details"],
    "documents": ["signed agreements", "letters or notices", "emails or texts", "proof of payment", "relevant attachments"],
    "dates": ["date of first issue", "date notice was received", "response deadlines", "upcoming hearings or meetings"],
    "damages": ["amounts claimed", "amounts paid", "losses or expenses", "mitigation steps"],
    "authority": ["decision maker", "who has signing authority", "who can confirm the facts"],
}


def split_sentences(text: str) -> list[str]:
    compact = re.sub(r"\s+", " ", text.strip())
    if not compact:
        return []
    return [part.strip() for part in re.split(r"(?<=[.!?])\s+", compact) if part.strip()]


def normalize_date(text: str) -> str | None:
    candidates = [
        ("%Y-%m-%d", text),
        ("%m/%d/%Y", text),
        ("%m/%d/%y", text),
        ("%B %d, %Y", text),
        ("%b %d, %Y", text),
    ]
    for fmt, value in candidates:
        try:
            return datetime.strptime(value, fmt).date().isoformat()
        except ValueError:
            continue
    return None


def extract_dates(text: str) -> list[DateHit]:
    hits: list[DateHit] = []
    seen: set[tuple[str, str]] = set()
    sentences = split_sentences(text)
    for sentence in sentences:
        for pattern in DATE_PATTERNS:
            for match in pattern.finditer(sentence):
                raw = match.group(0)
                key = (raw.lower(), sentence.lower())
                if key in seen:
                    continue
                seen.add(key)
                hits.append(DateHit(text=raw, sentence=sentence, normalized=normalize_date(raw)))
    return hits


def summarize_situation(task: str, jurisdiction: str, context: str, notes: str) -> str:
    sentences = split_sentences(notes)
    lead = sentences[:3] or ["No detailed notes were provided yet."]
    context_line = context.strip() or "No case context provided."
    jurisdiction_line = jurisdiction.strip() or "Jurisdiction not specified."
    return (
        f"**Task:** {task}\n\n"
        f"**Jurisdiction:** {jurisdiction_line}\n\n"
        f"**Context:** {context_line}\n\n"
        + "\n".join(f"- {sentence}" for sentence in lead)
    )


def generate_missing_facts(task: str, jurisdiction: str, notes: str) -> list[str]:
    lowered = notes.lower()
    missing: list[str] = []
    if not jurisdiction.strip():
        missing.append("Confirm the governing jurisdiction and any venue or forum details.")
    if not any(word in lowered for word in ["client", "tenant", "employee", "company", "landlord", "vendor"]):
        missing.append("Identify each party and their role in the matter.")
    if not any(word in lowered for word in ["letter", "email", "notice", "contract", "agreement", "invoice"]):
        missing.append("Collect the key documents, notices, messages, and attachments.")
    if not any(word in lowered for word in ["paid", "amount", "$", "loss", "damage", "charge"]):
        missing.append("Confirm amounts at issue, losses, payments, and supporting proof.")
    if not extract_dates(notes):
        missing.append("Add dates for the first event, important communications, deadlines, and next scheduled step.")

    task_specific = {
        "Client intake": "Ask what outcome the client wants and what deadline or urgency they are worried about.",
        "Document summary": "Confirm the document type, date, author, recipient, and whether the full document was reviewed.",
        "Email draft": "Confirm the intended recipient, tone, attachments, and whether counsel should preserve privilege language.",
        "Missing facts checklist": "Separate facts known from facts assumed, disputed, or still missing.",
        "Timeline extraction": "Confirm exact dates for ambiguous references such as 'last week' or month-only entries.",
        "Risk triage": "Identify deadlines, limitation periods, confidentiality concerns, and facts that could change the assessment.",
    }
    missing.append(task_specific.get(task, task_specific["Client intake"]))
    return dedupe(missing)


def extract_timeline(notes: str) -> list[str]:
    hits = extract_dates(notes)
    if not hits:
        return ["No explicit dates found. Add dates or deadlines before relying on this timeline."]
    return [
        f"- **{hit.normalized or hit.text}:** {hit.sentence}"
        for hit in hits
    ]


def generate_draft(task: str, jurisdiction: str, context: str, notes: str) -> str:
    if task == "Email draft":
        return (
            "Subject: Follow-up on documents and next steps\n\n"
            "Dear [Name],\n\n"
            "Thank you for the update. To help counsel review the matter efficiently, "
            "please send any relevant documents, notices, emails, invoices, payment records, "
            "and timeline details connected to the issue. If there are upcoming deadlines or "
            "scheduled meetings, please flag those dates in your reply.\n\n"
            "Once counsel has reviewed the materials, they can advise on next steps.\n\n"
            "Best,\n[Draft for lawyer review]"
        )
    if task == "Risk triage":
        return (
            "Next action: flag any limitation periods, response deadlines, privilege concerns, "
            "document preservation needs, and facts that are disputed or unsupported. Do not "
            "communicate legal conclusions until counsel has reviewed the record."
        )
    if task == "Timeline extraction":
        return "Next action: confirm ambiguous dates, source each event to a document or witness, and mark any hard deadlines."
    if task == "Document summary":
        return "Next action: attach the source document, identify who created it, and ask counsel to verify material terms and deadlines."
    if task == "Missing facts checklist":
        return "Next action: send the checklist to the client or internal team, then update the case note with confirmed answers."
    return "Next action: complete intake, collect source documents, confirm urgency, and route the file for lawyer review."


def generate_review_checklist(task: str) -> list[str]:
    base = [
        "Verify jurisdiction, parties, dates, and document sources.",
        "Separate confirmed facts from assumptions and disputed statements.",
        "Check for deadlines, limitation periods, court dates, or notice periods.",
        "Review privilege, confidentiality, and conflicts before sending drafts.",
        "Revise tone and content before any client-facing or opposing-party communication.",
    ]
    if task == "Email draft":
        base.insert(0, "Confirm recipient, sender, attachments, and whether reply-all is appropriate.")
    if task == "Risk triage":
        base.insert(0, "Escalate urgent deadlines or possible irreversible harm to counsel immediately.")
    return base


def dedupe(items: Iterable[str]) -> list[str]:
    output: list[str] = []
    seen: set[str] = set()
    for item in items:
        key = item.lower()
        if key not in seen:
            seen.add(key)
            output.append(item)
    return output


def call_model_backend(task: str, jurisdiction: str, context: str, notes: str) -> dict[str, object]:
    """Future integration point for Modal, llama.cpp, or another small-model backend."""
    return {
        "summary": summarize_situation(task, jurisdiction, context, notes),
        "missing_facts": generate_missing_facts(task, jurisdiction, notes),
        "timeline": extract_timeline(notes),
        "draft": generate_draft(task, jurisdiction, context, notes),
        "review_checklist": generate_review_checklist(task),
    }


def render_output(task: str, jurisdiction: str, context: str, notes: str) -> str:
    if not notes.strip() and not context.strip():
        return (
            "## Add Notes to Begin\n\n"
            "Enter fictional or sanitized case notes, then run the assistant. Do not enter real client secrets in this prototype."
        )

    result = call_model_backend(task, jurisdiction, context, notes)
    missing_facts = "\n".join(f"- {item}" for item in result["missing_facts"])
    review_checklist = "\n".join(f"- {item}" for item in result["review_checklist"])
    timeline = "\n".join(result["timeline"])

    return f"""## Situation Summary

{result["summary"]}

## Missing Facts

{missing_facts}

## Timeline / Date Extraction

{timeline}

## Draft Next Action

{escape(str(result["draft"]))}

## Lawyer Review Checklist

{review_checklist}

## Safety Note

{SAFETY_NOTE}
"""


