    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS episodic_memory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            query TEXT UNIQUE,
            action_json TEXT,
            q_value REAL
        )
    """)
    # Seed default memories if the database is newly initialized
    cursor.execute("SELECT COUNT(*) FROM episodic_memory")
    if cursor.fetchone()[0] == 0:
        baseline_memories = [
            ("draw a red circle", json.dumps([{"shape": "circle", "color": "red", "size": 100, "x": "center", "y": "center"}]), 1.0),
            ("make a blue square", json.dumps([{"shape": "square", "color": "blue", "size": 120, "x": "center", "y": "center"}]), 1.0),
            ("clear canvas", json.dumps([{"shape": "clear", "color": "white", "size": 0}]), 1.0)
        ]
        cursor.executemany("INSERT INTO episodic_memory (query, action_json, q_value) VALUES (?, ?, ?)", baseline_memories)
        conn.commit()
    conn.close()

def levenshtein_similarity(s1: str, s2: str) -> float:
    s1 = s1.lower().strip().strip(".?,!")
    s2 = s2.lower().strip().strip(".?,!")
    if s1 == s2:
        return 1.0
    m, n = len(s1), len(s2)
    if max(m, n) == 0:
        return 1.0

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

    return 1.0 - (dp[m][n] / max(m, n))

def find_memory_match(query: str, threshold: float = 0.75) -> dict:
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("SELECT query, action_json, q_value FROM episodic_memory")
    rows = cursor.fetchall()
    conn.close()

    best_match = None
    max_sim = 0.0

    for db_query, action_json, q_value in rows:
        sim = levenshtein_similarity(query, db_query)
        if sim > max_sim:
            max_sim = sim
            best_match = (db_query, action_json, q_value)

    if max_sim >= threshold and best_match:
        return {
            "matched_query": best_match[0],
            "action": json.loads(best_match[1]),
            "q_value": best_match[2],
            "similarity": max_sim
        }
    return None

