@spaces.GPU
def run_gemma_generation(prompt: str) -> str:
    if llm_model is None or tokenizer is None:
        raise ValueError("Gemma model is offline.")

    llm_model.to("cuda")
    inputs = tokenizer(prompt, return_tensors="pt").to("cuda")
    with torch.no_grad():
        outputs = llm_model.generate(
            **inputs,
            max_new_tokens=180,
            do_sample=False
        )
    response = tokenizer.decode(outputs[0][inputs.input_ids.shape[1]:], skip_special_tokens=True)

    # Unload model back to CPU to release GPU VRAM
    llm_model.to("cpu")
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    return response

def rule_based_fallback(user_text: str) -> list:
    lower_text = user_text.lower()

    # Split text into multiple commands by separators
    parts = re.split(r'\band\b|\bthen\b|,', lower_text)
    actions = []

    colors_list = ["red", "blue", "green", "yellow", "orange", "purple", "pink", "black", "white", "cyan", "magenta"]
    shapes_list = ["circle", "square", "rectangle", "triangle", "star", "pentagon", "hexagon", "oval", "heart", "line", "arrow", "text", "clear", "wipe", "reset"]

    for part in parts:
        part = part.strip()
        if not part:
            continue

        # 1. Check if it's a clear command
        if any(w in part for w in ["clear", "wipe", "reset"]):
            actions.append({"shape": "clear", "color": "white", "size": 0})
            continue

        # 2. Extract Color
        color = "black"
        for c in colors_list:
            if c in part:
                color = c
                break

        # 3. Extract Size
        size = 100
        size_match = re.search(r"\b(\d+)\b", part)
        if size_match:
            val = int(size_match.group(1))
            if 30 <= val <= 300:
                size = val

        # 4. Extract position x and y
        px = "center"
        if "left" in part:
            px = "left"
        elif "right" in part:
            px = "right"

        py = "center"
        if "top" in part:
            py = "top"
        elif "bottom" in part:
            py = "bottom"

        # 5. Check if it is a freehand path command
        if any(w in part for w in ["path", "freehand", "go", "move", "draw line to"]):
            operations = []
            operations.append({"type": "start", "x": px, "y": py})

            # Simple word-token scanning for direction steps
            words = part.replace(",", " ").split()
            for i, word in enumerate(words):
                if word in ["right", "east"] and i + 1 < len(words):
                    val = re.sub("[^0-9]", "", words[i+1])
                    if val: operations.append({"type": "line", "dx": int(val), "dy": 0})
                elif word in ["left", "west"] and i + 1 < len(words):
                    val = re.sub("[^0-9]", "", words[i+1])
                    if val: operations.append({"type": "line", "dx": -int(val), "dy": 0})
                elif word in ["down", "south"] and i + 1 < len(words):
                    val = re.sub("[^0-9]", "", words[i+1])
                    if val: operations.append({"type": "line", "dx": 0, "dy": int(val)})
                elif word in ["up", "north"] and i + 1 < len(words):
                    val = re.sub("[^0-9]", "", words[i+1])
                    if val: operations.append({"type": "line", "dx": 0, "dy": -int(val)})
                elif word in ["dot", "point"]:
                    operations.append({"type": "dot", "radius": 8})

            if len(operations) > 1:
                actions.append({
                    "shape": "path",
                    "color": color,
                    "thickness": 5,
                    "operations": operations
                })
            continue

        # Text / label commands (per Agents.md roadmap)
        text_match = re.search(r'["\']([^"\']+)["\']', part)
        is_text_cmd = any(w in part for w in ["text", "write", "say", "label", "title"])
        if is_text_cmd:
            label = text_match.group(1).strip() if text_match else (part.split()[-1] if len(part.split()) > 1 else "label")
            font_size = max(24, min(size, 160))
            actions.append({
                "shape": "text",
                "text": label,
                "color": color,
                "size": font_size,
                "x": px,
                "y": py
            })
            continue

        # 6. Check for standard shape types
        shape_found = None
        for s in shapes_list:
            if s in part:
                shape_found = s
                break

        # Handle line/arrow coordinates fallback
        if shape_found in ["line", "arrow"]:
            start_x = "left" if "left" in part else "center"
            start_y = "top" if "top" in part else "center"
            end_x = 380 if "right" in part else 250
            end_y = 380 if "bottom" in part else 250
            actions.append({
                "shape": shape_found,
                "color": color,
                "start_x": start_x,
                "start_y": start_y,
                "end_x": end_x,
                "end_y": end_y
            })
        elif shape_found:
            actions.append({
                "shape": shape_found,
                "color": color,
                "size": size,
                "x": px,
                "y": py
            })
        else:
            # Fallback default shape
            actions.append({
                "shape": "circle",
                "color": color,
                "size": size,
                "x": px,
                "y": py
            })

    return actions

def run_gemma_generation_cpu(prompt: str) -> str:
    if llm_model is None or tokenizer is None:
        raise ValueError("Gemma model is offline.")

    # Run fully on CPU
    llm_model.to("cpu")
    inputs = tokenizer(prompt, return_tensors="pt").to("cpu")
    with torch.no_grad():
        outputs = llm_model.generate(
            **inputs,
            max_new_tokens=180,
            do_sample=False
        )
    response = tokenizer.decode(outputs[0][inputs.input_ids.shape[1]:], skip_special_tokens=True)
    return response

def query_gemma_interpreter(user_text: str) -> list:
    if llm_model is None or tokenizer is None:
        return rule_based_fallback(user_text)

    prompt = f"""You are an ASR command interpreter converting raw spoken text into a strict JSON list of drawing actions.
Available shapes: "circle", "square", "rectangle", "triangle", "star", "pentagon", "hexagon", "oval", "heart", "line", "arrow", "path", "text", "clear"
Available colors: any standard CSS color name or hex code (e.g. "red", "blue", "#ff00ff", "cyan").
Available sizes: integer between 30 and 300.
Available positions:
- x: "left", "right", "center", or number
- y: "top", "bottom", "center", or number

Output JSON schema definitions:
1. For standard shapes:
{{"shape": "circle", "color": "red", "size": 100, "x": "center", "y": "center"}}

2. For line or arrow:
{{"shape": "line", "color": "blue", "start_x": "center", "start_y": "center", "end_x": 380, "end_y": 380}}

3. For path-based freehand drawing (move, go, draw line, dot):
{{
  "shape": "path",
  "color": "black",
  "thickness": 5,
  "operations": [
    {{"type": "start", "x": "center", "y": "center"}},
    {{"type": "line", "dx": 50, "dy": 0}},
    {{"type": "line", "dx": 0, "dy": 100}},
    {{"type": "dot", "radius": 8}}
  ]
}}

4. For text labels / annotations (write, say, label, text):
{{"shape": "text", "text": "Hello", "color": "black", "size": 48, "x": "center", "y": "center"}}

Input text: "{user_text}"
Output a strict JSON array of these objects only, no markdown formatting blocks, no extra words.
Example: [{{"shape": "circle", "color": "red", "size": 80, "x": "left", "y": "top"}}, {{"shape": "square", "color": "blue", "size": 120, "x": "right", "y": "bottom"}}]"""

    response = None
    try:
        print("Attempting Gemma generation on ZeroGPU...")
        response = run_gemma_generation(prompt)
    except Exception as gpu_err:
        print(f"ZeroGPU execution failed ({str(gpu_err)}). Trying CPU fallback...")
        try:
            response = run_gemma_generation_cpu(prompt)
        except Exception as cpu_err:
            print(f"CPU fallback generation failed: {str(cpu_err)}")
            return rule_based_fallback(user_text)

    if not response:
        return rule_based_fallback(user_text)

    try:
        print("Gemma raw response:", response)

        cleaned_json = response.strip()
        match = re.search(r"\[.*?\]", cleaned_json, re.DOTALL)
        if match:
            cleaned_json = match.group(0)
        else:
            match_brace = re.search(r"\{.*?\}", cleaned_json, re.DOTALL)
            if match_brace:
                cleaned_json = "[" + match_brace.group(0) + "]"

        return json.loads(cleaned_json)
    except Exception as e:
        print(f"Gemma JSON parsing failed: {str(e)}")
        return rule_based_fallback(user_text)

