# ==========================================
app = Server()

@app.post("/api/transcribe")
async def transcribe_endpoint(audio: UploadFile = File(...)):
    if asr_pipe is None:
        return {
            "transcription": "ASR engine is offline.",
            "status": "ASR Offline Fallback",
            "action": [{"shape": "circle", "color": "red", "size": 80, "x": "center", "y": "center"}],
            "q_value": 0.0,
            "similarity": 0.0
        }

    temp_path = "temp_asr_audio.wav"
    try:
        content = await audio.read()
        with open(temp_path, "wb") as f:
            f.write(content)

        # Whisper Tiny executes on CPU instantly
        result = asr_pipe(temp_path)
        raw_text = result.get("text", "").strip()
    except Exception as e:
        raw_text = ""
        print(f"ASR transcription failed: {str(e)}")
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

    if not raw_text:
        return {
            "transcription": "",
            "status": "No speech detected",
            "action": [],
            "q_value": 0.0,
            "similarity": 0.0
        }

    # MemRL Memory Lookup
    match = find_memory_match(raw_text, threshold=0.75)

    if match and match["q_value"] >= 0.8:
        return {
            "transcription": raw_text,
            "status": "MemRL Match Found (Auto-Executed)",
            "action": match["action"],
            "q_value": match["q_value"],
            "similarity": match["similarity"]
        }
    elif match and match["q_value"] >= 0.4:
        return {
            "transcription": raw_text,
            "status": "MemRL Suggestion (Low Confidence)",
            "action": match["action"],
            "q_value": match["q_value"],
            "similarity": match["similarity"]
        }
    else:
        # Query Gemma base policy
        action = query_gemma_interpreter(raw_text)
        return {
            "transcription": raw_text,
            "status": "MemRL Miss - Queried Gemma",
            "action": action,
            "q_value": 0.0,
            "similarity": 0.0
        }

class ReinforceRequest(BaseModel):
    query: str
    action_json: str
    reward: float
    corrected_action_json: str = None

@app.post("/api/reinforce")
def reinforce_endpoint(req: ReinforceRequest):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()

    query = req.query.lower().strip()
    alpha = 0.3
    initial_q = 0.5

    cursor.execute("SELECT action_json, q_value FROM episodic_memory WHERE query = ?", (query,))
    row = cursor.fetchone()

    msg = ""
    if req.reward == 1.0:
        # Accept Suggestion / Direct execution success
        # If a correction was previewed and accepted, prefer the corrected_action_json so the good mapping is stored.
        target_action = req.corrected_action_json or req.action_json
        if row:
            old_action, old_q = row
            new_q = old_q + alpha * (1.0 - old_q)
            cursor.execute("UPDATE episodic_memory SET action_json = ?, q_value = ? WHERE query = ?", (target_action, new_q, query))
            msg = f"Reinforced memory '{query}' (corrected) Q-value to {new_q:.3f}."
        else:
            new_q = initial_q + alpha * (1.0 - initial_q) # 0.65
            cursor.execute("INSERT INTO episodic_memory (query, action_json, q_value) VALUES (?, ?, ?)", 
                           (query, target_action, new_q))
            msg = f"Created new memory '{query}' with Q-value {new_q:.3f}."
    else:
        # Rejected or corrected by user
        if req.corrected_action_json:
            # Overwrite with corrected canvas mapping at direct execution threshold (0.80)
            corrected_action = req.corrected_action_json
            new_q = 0.80
            if row:
                cursor.execute("UPDATE episodic_memory SET action_json = ?, q_value = ? WHERE query = ?", 
                               (corrected_action, new_q, query))
            else:
                cursor.execute("INSERT INTO episodic_memory (query, action_json, q_value) VALUES (?, ?, ?)", 
                               (query, corrected_action, new_q))
            msg = f"Saved user manual override mapping for '{query}' with Q-value {new_q:.3f}."
        else:
            # Rejection / Undo, decay the Q-value
            if row:
                old_action, old_q = row
                new_q = old_q + alpha * (0.0 - old_q)
                cursor.execute("UPDATE episodic_memory SET q_value = ? WHERE query = ?", (new_q, query))
                msg = f"Decayed memory '{query}' Q-value to {new_q:.3f}."
            else:
                msg = f"No memory mapping found for '{query}' to decay."

    conn.commit()
    conn.close()
    return {"status": "success", "message": msg}

@app.get("/api/memories")
def memories_endpoint():
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("SELECT query, action_json, q_value FROM episodic_memory ORDER BY q_value DESC")
    rows = cursor.fetchall()
    conn.close()

    memories = []
    for query, action_json, q_value in rows:
        memories.append({
            "query": query,
            "action": json.loads(action_json),
            "q_value": round(q_value, 3)
        })
    return {"memories": memories}

@app.post("/api/clear_memories")
def clear_memories_endpoint():
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("DROP TABLE IF EXISTS episodic_memory")
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS episodic_memory (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            query TEXT UNIQUE,
            action_json TEXT,
            q_value REAL
        )
    """)
    conn.commit()
    conn.close()
    return {"status": "success", "message": "All episodic memories cleared."}

