/* ---- simulation controls card (CHANGE 1) ---- */
/* Override Gradio theme vars at the card scope so every nested control
   (dropdown, slider, number box) inherits the dark palette — robust to
   Gradio's internal class names. */
#simctl {
    --block-background-fill: #1a1b26;
    --block-border-color: #2a2b36;
    --background-fill-primary: #1a1b26;
    --background-fill-secondary: #14151d;
    --panel-background-fill: #1a1b26;
    --input-background-fill: #101019;
    --input-background-fill-focus: #14151d;
    --input-border-color: #2a2b36;
    --input-border-color-focus: #5a4a1f;
    --border-color-primary: #2a2b36;
    --body-text-color: #e8eaf2;
    --body-text-color-subdued: #9aa0b5;
    --neutral-700: #c8cce0;
    background: #1a1b26 !important; border: 1px solid #2a2b36 !important;
    border-radius: 12px !important; padding: 12px 12px 14px !important; }
#simctl span, #simctl label { color: #c8cce0 !important; }
/* belt-and-suspenders: dark the actual control elements + dropdown popup */
#simctl input:not([type="range"]) { background: #101019 !important;
    color: #e8eaf2 !important; border-color: #2a2b36 !important; box-shadow: none !important; }
