def evidence_urls(profile):
    urls = []
    for item in profile.get("evidence", []):
        url = str(item.get("source_url", "")).strip()
        if url and url not in urls:
            urls.append(url)
    return urls


def trace_sources(trace):
    sources = []
    urls = set()
    for item in trace:
        for result in item.get("detail", {}).get("results", []):
            url = str(result.get("url", "")).strip()
            if not url or url in urls:
                continue
            urls.add(url)
            sources.append(
                {
                    "source_title": str(result.get("title", ""))[:180],
                    "source_url": url[:500],
                    "snippet": str(result.get("snippet", ""))[:700],
                }
            )
    return sources


def image_candidates(profile, trace):
    urls = []
    primary = str(profile.get("image_url", "")).strip()
    if primary:
        urls.append(primary)
    counts = {}
    order = []
    for item in trace:
        if item.get("step") != "image_search":
            continue
        for result in item.get("detail", {}).get("results", []):
            url = str(result.get("image_url", "")).strip()
            if not url:
                continue
            if url not in counts:
                order.append(url)
            counts[url] = counts.get(url, 0) + 1
    for url in sorted(order, key=lambda u: counts[u], reverse=True):
        if url not in urls:
            urls.append(url)
    return urls


def detect_image_type(data):
    if data.startswith(b"\xff\xd8\xff"):
        return "jpeg"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"
    if data.startswith(b"GIF87a") or data.startswith(b"GIF89a"):
        return "gif"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "webp"
    return ""


def download_persona_image(urls, run_id):
    ensure_data_dir()
    headers = {"User-Agent": "Mozilla/5.0", "Accept": "image/*"}
    for url in urls:
        if not is_http_url(url):
            continue
        try:
            response = requests.get(url, headers=headers, timeout=20)
        except Exception:
            continue
        if response.status_code != 200:
            continue
        data = response.content
        ext = detect_image_type(data)
        if not ext or len(data) < 2048:
            continue
        path = IMAGE_DIR / f"{run_id}.{ext}"
        path.write_bytes(data)
        return path.as_posix()
    return ""


