def complete_profile_sources(profile, trace):
    urls = set(evidence_urls(profile))
    evidence = list(profile.get("evidence", []))
    for source in trace_sources(trace):
        if len(urls) >= MIN_RESEARCH_SOURCES:
            break
        url = source["source_url"]
        if url in urls:
            continue
        urls.add(url)
        evidence.append(
            {
                "claim": "Public source used by the research agent to ground the persona dossier.",
                "source_title": source["source_title"],
                "source_url": url,
            }
        )
    profile["evidence"] = evidence[:8]
    if not profile.get("source_url") and profile["evidence"]:
        profile["source_url"] = profile["evidence"][0].get("source_url", "")
    return profile


def refine_profile_sources(client, messages, trace, profile):
    if len(evidence_urls(profile)) >= MIN_RESEARCH_SOURCES:
        return profile
    sources = trace_sources(trace)[:8]
    if len(sources) < MIN_RESEARCH_SOURCES:
        return complete_profile_sources(profile, trace)
    messages.append(
        {
            "role": "user",
            "content": f"The dossier used fewer than {MIN_RESEARCH_SOURCES} distinct source URLs. Rebuild the same JSON dossier and include evidence from at least {MIN_RESEARCH_SOURCES} distinct sources from this list:\n{json.dumps(sources, ensure_ascii=False)}",
        }
    )
    completion = client.chat.completions.create(
        model=GENERATION_MODEL,
        messages=messages,
        tools=[BROWSER_SEARCH_TOOL, IMAGE_SEARCH_TOOL],
        tool_choice="none",
        temperature=SAMPLING_TEMPERATURE,
        top_p=SAMPLING_TOP_P,
        extra_body={"top_k": SAMPLING_TOP_K},
    )
    return complete_profile_sources(normalize_profile(parse_json_object(completion.choices[0].message.content or "")), trace)


def build_profile_with_agent(article):
    trace = []
    client = make_client(GENERATION_PROVIDER)
    if client is None:
        raise RuntimeError("HF_TOKEN is missing. Add it to the environment or Hugging Face Space secrets.")
    prompt = f"""
Build a grounded behavioral persona dossier for simulating this public person.
Use browser_search before returning the final JSON. Search for evidence about writing style, thinking style, expertise, interviews, speeches, letters, public work, and known limitations. Collect evidence from at least {MIN_RESEARCH_SOURCES} distinct public source URLs.
Use image_search to find a real, working photo or portrait URL for this person and use one of the returned image URLs as image_url. Do not invent image URLs.
If there is no direct photo of the person, do not pick an arbitrary unrelated image: prefer an image that recurs across the image_search results, because a repeatedly returned image is likely genuinely associated with this person and is the more relevant choice.
Return only valid JSON with keys:
canonical_name: string,
description: string,
source_url: string,
image_url: string,
short_profile: string,
key_facts: array of 5-8 short strings,
knowledge_domains: array of short strings,
reasoning_style: string,
writing_style: string,
likely_blind_spots: string,
style_hypothesis: string,
persona_prompt_notes: string,
evidence: array of objects with claim, source_title, source_url.
Evidence must include at least {MIN_RESEARCH_SOURCES} distinct source_url values. Focus on observable expertise, habits of thought, communication style, likely strengths, likely blind spots, and how this person would approach unfamiliar benchmark tasks. Do not invent private facts.

Person input or seed title: {article['title']}
Description: {article.get('description', '')}
Summary: {article.get('summary', '')}
Article extract:
{article.get('extract', '')[:5500]}
"""
    messages = [
        {
            "role": "system",
            "content": "You are a web research agent that builds concise, evidence-grounded persona simulation dossiers. Use the search tool when you need public evidence. Finish with valid JSON only.",
        },
        {"role": "user", "content": prompt},
    ]
    try:
        for round_index in range(4):
            completion = client.chat.completions.create(
                model=GENERATION_MODEL,
                messages=messages,
                tools=[BROWSER_SEARCH_TOOL, IMAGE_SEARCH_TOOL],
                tool_choice="auto",
                temperature=SAMPLING_TEMPERATURE,
                top_p=SAMPLING_TOP_P,
                extra_body={"top_k": SAMPLING_TOP_K},
            )
            message = completion.choices[0].message
            tool_calls = getattr(message, "tool_calls", None) or []
            if not tool_calls:
                profile = normalize_profile(parse_json_object(message.content or ""))
                profile = refine_profile_sources(client, messages, trace, profile)
                trace.append({"step": "infer_persona_profile", "status": "ok", "provider": GENERATION_PROVIDER, "detail": profile})
                return profile, trace
            serialized_calls = [serialize_tool_call(call) for call in tool_calls]
            messages.append({"role": "assistant", "content": message.content or "", "tool_calls": serialized_calls})
            for call in tool_calls:
                arguments = parse_tool_arguments(call.function.arguments)
                query = str(arguments.get("query", "")).strip()[:300]
                if call.function.name == "image_search":
                    results = image_search(query)
                    step = "image_search"
                else:
                    results = browser_search(query)
                    step = "browser_search"
                trace.append(
                    {
                        "step": step,
                        "status": "ok",
                        "provider": "ddgs",
                        "detail": {"round": round_index + 1, "query": query, "results": results},
                    }
                )
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": call.id,
                        "name": call.function.name,
                        "content": json.dumps(results, ensure_ascii=False),
                    }
                )
        messages.append({"role": "user", "content": "Stop searching now and return the final valid JSON persona dossier."})
        completion = client.chat.completions.create(
            model=GENERATION_MODEL,
            messages=messages,
            tools=[BROWSER_SEARCH_TOOL, IMAGE_SEARCH_TOOL],
            tool_choice="none",
            temperature=SAMPLING_TEMPERATURE,
            top_p=SAMPLING_TOP_P,
            extra_body={"top_k": SAMPLING_TOP_K},
        )
        profile = normalize_profile(parse_json_object(completion.choices[0].message.content or ""))
        profile = refine_profile_sources(client, messages, trace, profile)
        trace.append({"step": "infer_persona_profile", "status": "ok", "provider": GENERATION_PROVIDER, "detail": profile})
        return profile, trace
    except Exception as exc:
        raise RuntimeError(f"Could not infer persona profile with {GENERATION_MODEL} via {GENERATION_PROVIDER}: {exc}") from exc


def build_system_prompt(person_name, article, profile):
    facts = "\n".join(f"- {fact}" for fact in profile.get("key_facts", []))
    knowledge = "\n".join(f"- {item}" for item in profile.get("knowledge_domains", []))
    source_url = profile.get("source_url") or article.get("url", "")
    return f"""
You are {person_name}.
Answer every benchmark task as {person_name} would answer it, using the public biography, expertise, habits of thought, communication style, and likely limitations below.
Do not answer as a generic assistant unless the persona itself would behave that way.
If the persona is unlikely to know something, reason from the persona's background instead of silently becoming a universal expert.
If the persona has distinctive expertise, priorities, temperament, or rhetorical style, let those traits shape the answer.

Public profile:
{profile.get('short_profile', '')}

Key facts:
{facts}

Knowledge domains:
{knowledge}

Reasoning style:
{profile.get('reasoning_style', '')}

Writing style:
{profile.get('writing_style', '')}

