Answer the open-ended question directly while staying in character.
Express the persona's likely stance, values, priorities, and reasoning style rather than a generic answer.
Source page: {source_url}
""".strip()


def generate_answer(task, system_prompt):
    client = make_client(GENERATION_PROVIDER)
    if client is None:
        raise RuntimeError("HF_TOKEN is missing. Add it to the environment or Hugging Face Space secrets.")
    try:
        completion = client.chat.completions.create(
            model=GENERATION_MODEL,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": task["prompt"]},
            ],
            temperature=SAMPLING_TEMPERATURE,
            top_p=SAMPLING_TOP_P,
            extra_body={"top_k": SAMPLING_TOP_K},
        )
        return completion.choices[0].message.content
    except Exception as exc:
        raise RuntimeError(f"HF API error for {GENERATION_MODEL} via {GENERATION_PROVIDER}: {exc}") from exc


def progress_html(message, value=0.0):
    percent = max(0.0, min(100.0, float(value) * 100))
    return f"""
    <div class="run-progress-panel">
        <div class="run-progress-head">
            <strong>Run progress</strong>
            <span>{escape(message)} - {percent:.1f}%</span>
        </div>
        <div class="run-progress-track">
            <div class="run-progress-fill" style="width:{percent:.1f}%"></div>
        </div>
    </div>
    """


def iter_benchmark_tasks(system_prompt, progress_start=0.22, progress_end=0.84):
    answers = [None] * len(BENCHMARK)
    workers = min(GENERATION_WORKERS, len(BENCHMARK))
    completed = 0
    yield progress_start, f"Gemma benchmark: 0/{len(BENCHMARK)} tasks"
    with ThreadPoolExecutor(max_workers=workers) as executor:
        futures = {executor.submit(generate_answer, task, system_prompt): (index, task) for index, task in enumerate(BENCHMARK)}
        for future in as_completed(futures):
            index, task = futures[future]
            answer = future.result()
            answers[index] = {
                "task_id": task["id"],
                "category": task["category"],
                "prompt": task["prompt"],
                "answer": answer,
            }
            completed += 1
            value = progress_start + (progress_end - progress_start) * completed / len(BENCHMARK)
            yield value, f"Gemma benchmark: {completed}/{len(BENCHMARK)} tasks"
    return answers


def run_benchmark_tasks(system_prompt):
    runner = iter_benchmark_tasks(system_prompt)
    while True:
        try:
            next(runner)
        except StopIteration as stop:
            return stop.value


def normalize_embedding_output(raw):
    arr = np.asarray(raw, dtype=np.float32)
    if arr.ndim == 1:
        return arr.reshape(1, -1)
    if arr.ndim == 3:
        return arr.mean(axis=1)
    return arr


def embed_one_text(text):
    client = make_client(EMBEDDING_PROVIDER)
    if client is None:
        raise RuntimeError("HF_TOKEN is missing. Add it to the environment or Hugging Face Space secrets.")
    raw = client.feature_extraction(text, model=EMBEDDING_MODEL)
    return normalize_embedding_output(raw)[0]


def iter_embed_texts(texts, progress_start=0.86, progress_end=0.98):
    if make_client(EMBEDDING_PROVIDER) is None:
        raise RuntimeError("HF_TOKEN is missing. Add it to the environment or Hugging Face Space secrets.")
    try:
        vectors = [None] * len(texts)
        workers = min(EMBEDDING_WORKERS, len(texts))
        completed = 0
        yield progress_start, f"Embedding answers: 0/{len(texts)}"
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {executor.submit(embed_one_text, text): index for index, text in enumerate(texts)}
            for future in as_completed(futures):
                vectors[futures[future]] = future.result()
                completed += 1
                value = progress_start + (progress_end - progress_start) * completed / len(texts)
                yield value, f"Embedding answers: {completed}/{len(texts)}"
        vectors = np.vstack(vectors)
        norms = np.linalg.norm(vectors, axis=1, keepdims=True)
        norms[norms == 0] = 1.0
        return vectors / norms, f"{EMBEDDING_MODEL} via {EMBEDDING_PROVIDER}"
    exc

