def find_initial_anchor(transcribed_text):
    normalized_input = normalize_arabic_text(transcribed_text)
    if not normalized_input or len(normalized_input.split()) < 2: 
        return None

    input_words = set(normalized_input.split())
    best_verse = None
    max_overlap = 0

    for verse in QURAN_DATABASE:
        verse_words = set(verse["normalized_text"].split())
        overlap = len(input_words.intersection(verse_words))
        if overlap > max_overlap:
            max_overlap = overlap
            best_verse = verse

    if max_overlap >= 2: 
        return best_verse
    return None

def align_and_format_diffs(canonical_str, transcribed_str, is_final=False):
    canonical_tokens = canonical_str.split()
    norm_canonical_tokens = [normalize_arabic_text(w) for w in canonical_tokens]
    norm_transcribed_tokens = [normalize_arabic_text(w) for w in transcribed_str.split()]

    matcher = difflib.SequenceMatcher(None, norm_canonical_tokens, norm_transcribed_tokens)
    opcodes = matcher.get_opcodes()

    html_output_tokens = []
    for tag, i1, i2, j1, j2 in opcodes:
        if tag == 'equal':
            for idx in range(i1, i2):
                html_output_tokens.append(f"<span class='correct-word'>{canonical_tokens[idx]}</span>")
        elif tag in ('replace', 'delete'):
            if not is_final and tag == 'delete' and i2 == len(norm_canonical_tokens) and j1 == len(norm_transcribed_tokens):
                continue
            for idx in range(i1, i2):
                html_output_tokens.append(f"<span class='error-word'>{canonical_tokens[idx]}</span>")

    return " ".join(html_output_tokens)

def deep_extract_text(obj):
    if isinstance(obj, str): return obj
    if isinstance(obj, (list, tuple)):
        for item in obj:
            extracted = deep_extract_text(item)
            if extracted: return extracted
    if obj is not None:
        for attr in ['text', 'words', 'transcript', 'predictions']:
            if hasattr(obj, attr):
                val = getattr(obj, attr)
                extracted = deep_extract_text(val)
                if extracted: return extracted
    return None

