def stream_transcribe(audio_chunk, stream_state):
    global model

    if not model or audio_chunk is None:
        return "<div class='quran-container'>جاري التهيئة...</div>", "<div class='surah-badge'>سورة غير محددة</div>", stream_state

    if stream_state is None:
        stream_state = {
            "audio": np.array([], dtype=np.float32), 
            "silent_chunks_count": 0, 
            "history_html": "",
            "current_ayah_raw": "",  
            "expected_db_idx": None, 
            "detected_surah": "سورة غير محددة"
        }

    temp_live_file = None
    try:
        sample_rate, audio_data = audio_chunk
        audio_data = audio_data.astype(np.float32)
        if np.max(np.abs(audio_data)) > 1.0: audio_data /= 32768.0
        if len(audio_data.shape) > 1: audio_data = audio_data.mean(axis=1)

        rms = np.sqrt(np.mean(audio_data**2)) if len(audio_data) > 0 else 0
        if rms < 0.005:
            stream_state["silent_chunks_count"] += 1
        else:
            stream_state["silent_chunks_count"] = 0

        if len(stream_state["audio"]) == 0:
            stream_state["audio"] = audio_data
        else:
            stream_state["audio"] = np.concatenate((stream_state["audio"], audio_data))

        waveform = torch.from_numpy(stream_state["audio"]).unsqueeze(0)
        if sample_rate != 16000:
            resampler = torchaudio.transforms.Resample(orig_freq=sample_rate, new_freq=16000)
            waveform = resampler(waveform)

        # إنشاء ملف مؤقت معزول تماماً ومحمي من التصادم لمنع تفجير الـ File Descriptor
        with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tmp_f:
            temp_live_file = tmp_f.name

        torchaudio.save(temp_live_file, waveform, 16000)

        transcriptions = model.transcribe([temp_live_file])
        current_raw_text = deep_extract_text(transcriptions)
        current_raw_text = current_raw_text.strip() if current_raw_text else ""
        current_raw_text = current_raw_text.replace("نهاية الدرس", "").strip()

        if stream_state["current_ayah_raw"]:
            total_current_speech = f"{stream_state['current_ayah_raw']} {current_raw_text}".strip()
        else:
            total_current_speech = current_raw_text

        if stream_state["expected_db_idx"] is None and total_current_speech:
            anchor_verse = find_initial_anchor(total_current_speech)
            if anchor_verse:
                stream_state["expected_db_idx"] = anchor_verse["db_index"]

        if stream_state["expected_db_idx"] is not None:
            active_target_verse = QURAN_DATABASE[stream_state["expected_db_idx"]]
            surah_index = active_target_verse["surah_num"] - 1
            stream_state["detected_surah"] = f"سورة {SURAH_NAMES[surah_index]}"

            live_aligned_text = align_and_format_diffs(active_target_verse["original_text"], total_current_speech, is_final=False)
            live_block = f"<span class='live-window'>{live_aligned_text}</span>"
        else:
            live_block = f"<span class='live-window'>{total_current_speech}</span>"

        if stream_state["history_html"]:
            full_html_output = f"{stream_state['history_html']} &nbsp;&nbsp; {live_block}".strip()
        else:
            full_html_output = live_block

        if stream_state["silent_chunks_count"] >= 3 and current_raw_text:
            if stream_state["expected_db_idx"] is not None:
                final_target = QURAN_DATABASE[stream_state["expected_db_idx"]]

                canonical_tokens = final_target["normalized_text"].split()
                norm_speech_tokens = [normalize_arabic_text(w) for w in total_current_speech.split()]
                matcher = difflib.SequenceMatcher(None, [normalize_arabic_text(w) for w in canonical_tokens], norm_speech_tokens)
                total_equal_words = sum(i2 - i1 for tag, i1, i2, j1, j2 in matcher.get_opcodes() if tag == 'equal')

                coverage_ratio = total_equal_words / len(canonical_tokens) if len(canonical_tokens) > 0 else 0.0

                if coverage_ratio >= 0.75:
                    final_aligned_segment = align_and_format_diffs(final_target["original_text"], total_current_speech, is_final=True)
                    committed_block = f"{final_aligned_segment} <span class='ayah-num'>﴿{final_target['ayah_num']}﴾</span>"

                    if stream_state["history_html"]:
                        stream_state["history_html"] = f"{stream_state['history_html']} &nbsp;&nbsp; {committed_block}".strip()
                    else:
                        stream_state["history_html"] = committed_block

                    stream_state["current_ayah_raw"] = ""
                    if stream_state["expected_db_idx"] + 1 < len(QURAN_DATABASE):
                        stream_state["expected_db_idx"] += 1
                else:
                    stream_state["current_ayah_raw"] = total_current_speech
            else:
                stream_state["current_ayah_raw"] = ""

            stream_state["audio"] = np.array([], dtype=np.float32)
            stream_state["silent_chunks_count"] = 0

            if stream_state["current_ayah_raw"] and stream_state["expected_db_idx"] is not None:
                current_target = QURAN_DATABASE[stream_state["expected_db_idx"]]
                partial_html = align_and_format_diffs(current_target["original_text"], stream_state["current_ayah_raw"], is_final=False)
                full_html_output = f"{stream_state['history_html']} &nbsp;&nbsp; <span class='live-window'>{partial_html}</span>".strip()
            else:
                full_html_output = stream_state["history_html"]

        if not full_html_output.strip():
            return "<div class='quran-container' style='color:#777; text-align:center;'>ابدأ التسميع الآن ليقوم المعلم الآلي بتصحيح تلاوتك بالترتيب التتابعي الصارم...</div>", "<div class='surah-badge'>سورة غير محددة</div>", stream_state

        final_ui_html = f"<div class='quran-container'>{full_html_output}</div>"
        formatted_surah_header = f"<div class='surah-badge'>{stream_state['detected_surah']}</div>"

        return final_ui_html, formatted_surah_header, stream_state

    except Exception as e:
        print(f"[STREAM ERROR] {e}")
        return f"<div class='quran-container'>حدث خطأ: {str(e)}</div>", "<div class='surah-badge'>خطأ</div>", stream_state

    finally:
        # إغلاق ومسح الملف المؤقت فوراً بمجرد انتهاء دورة القراءة الجارية لتحرير النظام
        if temp_live_file and os.path.exists(temp_live_file):
