def call_qwen(messages, max_tokens=60, temperature=0.85, timeout=8):
    """Call Qwen via DashScope or OpenRouter. Returns text or None on failure."""
    result = None

    # Try DashScope first
    if QWEN_KEY:
        try:
            resp = requests.post(
                "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
                headers={"Authorization": f"Bearer {QWEN_KEY}", "Content-Type": "application/json"},
                json={"model": QWEN_MODEL, "messages": messages, "max_tokens": max_tokens, "temperature": temperature, "top_p": 0.9},
                timeout=timeout,
            )
            if resp.status_code == 200:
                data = resp.json()
                result = data["choices"][0]["message"]["content"].strip().strip('"').strip("'")
                print(f"[OK] DashScope: {result[:60]}")
            else:
                print(f"[!] DashScope {resp.status_code}")
        except Exception as e:
            print(f"[!] DashScope error: {e}")

    # Fallback to OpenRouter
    if not result and OR_KEY:
        try:
            resp = requests.post(
                "https://openrouter.ai/api/v1/chat/completions",
                headers={"Authorization": f"Bearer {OR_KEY}", "Content-Type": "application/json"},
                json={"model": "qwen/qwen3.7-max", "messages": messages, "max_tokens": max_tokens, "temperature": temperature},
                timeout=timeout,
            )
            if resp.status_code == 200:
                data = resp.json()
                result = data["choices"][0]["message"]["content"].strip().strip('"').strip("'")
                print(f"[OK] OpenRouter: {result[:60]}")
            else:
                print(f"[!] OpenRouter {resp.status_code}")
        except Exception as e:
            print(f"[!] OpenRouter error: {e}")

    return result

