"""
UX Crime Scene — Gradio frontend (real 3-step wizard).

Local dev:
    export MODAL_ENDPOINT_URL="https://<your>--ux-crime-scene-qwen-web.modal.run"
    python app.py
"""

from __future__ import annotations

import base64
import html
import io
import os
import time
import traceback
import urllib.parse
from pathlib import Path

import gradio as gr
from PIL import Image

from annotate import annotate
from detective import CaseFile, investigate_agentic, save_case, fetch_case

HERE = Path(__file__).parent
ASSETS = HERE / "assets"

# Public URL of the tool (set this to the Space URL in production).
TOOL_URL = os.environ.get("PUBLIC_URL", "").strip() or \
    "https://huggingface.co/spaces/build-small-hackathon/ux-crime-scene"

ASSET_VARS = {
    "paper.jpg": "--asset-paper",
    "emblem.png": "--asset-emblem",
    "magnifier.png": "--asset-magnifier",
    "grade_seal.png": "--asset-grade",
    "stamp_confidential.png": "--asset-stamp-confidential",
    "stamp_guilty.png": "--asset-stamp-guilty",
    "desk_topdown.jpg": "--asset-desk",
}
_MIME = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg"}

STATIC_CSS = (HERE / "styles.css").read_text(encoding="utf-8")


def esc(v) -> str:
    return html.escape(str(v))


def _build_asset_style() -> tuple[str, dict[str, bool]]:
    overrides, present = [], {}
    for fname, var in ASSET_VARS.items():
        path = ASSETS / fname
        ok = path.exists()
        present[fname] = ok
        if ok:
            raw = path.read_bytes()
            mime = _MIME.get(path.suffix.lower(), "image/png")
            b64 = base64.b64encode(raw).decode("ascii")
            overrides.append(f"{var}: url('data:{mime};base64,{b64}');")
    if present.get("emblem.png"):
        overrides.append("--emblem-display: block;")
    style = "<style>\n:root{\n" + "\n".join(overrides) + "\n}\n</style>" if overrides else ""
    return style, present


ASSET_STYLE, ASSET_PRESENT = _build_asset_style()


def _asset_data_uri(fname: str) -> str:
    """Base64 data-URI for a finished asset, or '' if it isn't there."""
    path = ASSETS / fname
    if not path.exists():
        return ""
    mime = _MIME.get(path.suffix.lower(), "image/png")
    return f"data:{mime};base64,{base64.b64encode(path.read_bytes()).decode('ascii')}"


# The Inspector character (transparent PNGs). `point` accuses the evidence on the
# verdict screen; `lean` examines the scene during the sweep. Embedded once.
INSPECTOR_POINT = _asset_data_uri("inspector_point.png")
INSPECTOR_LEAN = _asset_data_uri("inspector_lean.png")
INSPECTOR_NOTES = _asset_data_uri("inspector_notes.png")
INSPECTOR_EXAMINE = _asset_data_uri("inspector_examine.png")
INSPECTOR_FINGER = _asset_data_uri("inspector_finger.png")


def _inspector_html(pose: str) -> str:
    """A noir detective who slides into the corner. `pose` is 'point' or 'lean'.
    Rendered inside a screen's HTML so he appears/leaves with that screen, and is
    position:fixed so he anchors to the viewport corner."""
    uri = INSPECTOR_POINT if pose == "point" else INSPECTOR_LEAN
    if not uri:
        return ""
    return (
        f'<div class="inspector-fig insp-{esc(pose)}" aria-hidden="true">'
        f'<img src="{uri}" alt=""/></div>'
    )


def _inspector_rotator_html() -> str:
    """During the sweep step, the Inspector rotates through the 4 corners of
    the viewport with different poses (lean=examines, notes=writing,
    examine=thinking, finger=pointing). Each slide gets its own animation
    timing so corners + poses cycle in lockstep."""
    # Corners chosen so each figure faces/points TOWARD the laptop in the centre:
    #   finger points down-right -> top-left
    #   notes faces left         -> top-right
    #   examine faces right      -> bottom-left  (looks toward the laptop)
    #   lean peers down-right    -> bottom-right
    poses = [
        ("finger",  INSPECTOR_FINGER,  "tl"),
        ("notes",   INSPECTOR_NOTES,   "tr"),
        ("examine", INSPECTOR_EXAMINE, "bl"),
        ("lean",    INSPECTOR_LEAN,    "br"),
    ]
    items = []
    for i, (pose, uri, corner) in enumerate(poses):
        if not uri:
            continue
        items.append(
            f'<div class="ir-slide ir-{corner}" style="--i:{i}" data-pose="{pose}">'
            f'<img src="{uri}" alt=""/></div>'
        )
    if not items:
        return ""
    return f'<div class="inspector-rotator" aria-hidden="true">{"".join(items)}</div>'

# ---------------------------------------------------------------------------
# Audio: noir soundtrack + SFX, embedded and driven client-side. A head <script>
# runs natively (unlike gr.HTML innerHTML scripts) so it can build the floating
# sound bubble and play SFX on button clicks / wizard-screen changes.
# ---------------------------------------------------------------------------
AUDIO_FILES = {
    "music": "music.mp3",
    "click": "sfx_click.mp3",
    "scan": "sfx_scan.mp3",
    "verdict": "sfx_verdict.mp3",
    "thud": "sfx_thud.mp3",
}

_AUDIO_JS = """
(function(){
  if (window.__uxcSound) return; window.__uxcSound = true;

  var music = null, verdictPlayed = false;
  // Master switch. Initial value comes from the consent gate (or a stored pref).
  var pref = sessionStorage.getItem('uxc_sound');   // 'on' | 'off' | null
  var state = { on: pref === 'on' };

  function ensureMusic(){
    if(!music){ music = new Audio(AUD.music); music.loop = true; music.volume = 0.5; }
    return music;
  }
  function alleyVideo(){ return document.getElementById('intro-alley-video'); }

  function applyState(){
    var b = document.getElementById('sound-bubble');
    var av = alleyVideo();
    if (state.on){
      ensureMusic(); music.play().catch(function(){});
      if (av){ av.muted = false; try{ av.volume = 1.0; }catch(e){} }
      if (b){ b.classList.add('on'); var t=b.querySelector('.sb-txt'); if(t) t.textContent='SOUND ON'; }
    } else {
      if (music) music.pause();
      if (av){ av.muted = true; }
      if (b){ b.classList.remove('on'); var t=b.querySelector('.sb-txt'); if(t) t.textContent='SOUND OFF'; }
    }
  }

  // Public API — the consent gate + bubble + SFX hooks all go through this.
  window.UXC = window.UXC || {};
  window.UXC.setSound = function(on){ state.on = !!on; sessionStorage.setItem('uxc_sound', on ? 'on':'off'); applyState(); };
  window.UXC.toggleSound = function(){ window.UXC.setSound(!state.on); };
  window.UXC.isSoundOn = function(){ return state.on; };
  window.UXC.play = function(key, vol){
    if (!state.on) return;                  // master gate: nothing plays when off
    try { var a = new Audio(AUD[key]); a.volume = (vol==null?0.6:vol); a.play().catch(function(){}); } catch(e){}
  };

  // Floating master toggle (bottom-right). Controls EVERYTHING now.
  function makeBubble(){
    if (document.getElementById('sound-bubble')) return;
    var b = document.createElement('button');
    b.id = 'sound-bubble'; b.type = 'button';
    b.setAttribute('aria-label','Toggle all sound');
    b.innerHTML = '<span class="sb-ico">\\u266A</span><span class="sb-txt">SOUND OFF</span>';
    document.body.appendChild(b);
    b.addEventListener('click', function(){ window.UXC.toggleSound(); });
    applyState();
  }
  if (document.readyState!=='loading') makeBubble();
  else document.addEventListener('DOMContentLoaded', makeBubble);

  // SFX: button clicks
  document.addEventListener('click', function(e){
    var t = e.target && e.target.closest && e.target.closest('#investigate-btn, #newcase-btn');
    if (t) window.UXC.play('click', 0.6);
  }, true);
  // SFX: thud when an image is dropped/picked
  var thudFired = false;
  document.addEventListener('change', function(e){
    var inp = e.target && e.target.matches && e.target.matches('#evidence-drop input[type=file]');
    if (inp && !thudFired){ window.UXC.play('thud', 0.85); thudFired = true; setTimeout(function(){thudFired=false;}, 1500); }
  }, true);
  // SFX: a single stamp hit on the verdict reveal
  function vis(sel){ var el=document.querySelector(sel); return !!(el && el.offsetParent !== null); }
  new MutationObserver(function(){
    var verdict = vis('.screen-verdict');
    if (verdict && !verdictPlayed){ verdictPlayed=true; window.UXC.play('verdict', 0.55); }
    if (!verdict){ verdictPlayed=false; }
  }).observe(document.body, {attributes:true, childList:true, subtree:true, attributeFilter:['style','class']});
})();
"""


def _build_audio_head() -> str:
    import json
    urls = {}
    for key, fname in AUDIO_FILES.items():
        p = ASSETS / "audio" / fname
        if p.exists():
            b64 = base64.b64encode(p.read_bytes()).decode("ascii")
            urls[key] = f"data:audio/mpeg;base64,{b64}"
    if not urls:
        return ""
    return "<script>\nvar AUD=" + json.dumps(urls) + ";\n" + _AUDIO_JS + "\n</script>"


AUDIO_HEAD = _build_audio_head()


_VOICE_JS = """
(function(){
  if (window.__uxcVoice) return; window.__uxcVoice = true;
  var V = VOICE_LINES || [];
  if (!V.length) return;
  var bag = [], lastIdx = -1, current = null, timer = null;
  function refill(){
    bag = V.map(function(_,i){ return i; });
    for (var i=bag.length-1;i>0;i--){ var j=Math.floor(Math.random()*(i+1)); var t=bag[i];bag[i]=bag[j];bag[j]=t; }
    if (bag.length>1 && bag[0]===lastIdx){ var t=bag[0];bag[0]=bag[1];bag[1]=t; }   // no immediate repeat
  }
  function sweepActive(){
    // Active the moment the laptop (sweep) is in the DOM — voices start right
    // away, even under the brief intro video (which has no audio of its own).
    var laptop = document.querySelector('.laptop-stage');
    if (!laptop) return false;
    var verdict = document.querySelector('.screen-verdict');
    if (verdict && verdict.getBoundingClientRect().height > 100) return false;
    return true;
  }
  function stop(){ if(timer){clearTimeout(timer);timer=null;} if(current){try{current.pause();}catch(e){} current=null;} }
  function schedule(ms){ clearTimeout(timer); timer = setTimeout(playOne, ms); }
  function playOne(){
    if (!sweepActive()){ stop(); return; }
    if (!window.UXC || !window.UXC.isSoundOn()){ schedule(2500); return; }   // respect master sound switch
    if (current){ schedule(1500); return; }
    if (bag.length===0) refill();
    var idx = bag.shift(); lastIdx = idx;
    try {
      var a = new Audio(V[idx]); a.volume = 0.46; current = a;   /* ~50% */
      a.onended = function(){ current=null; schedule(2600 + Math.random()*3200); };
      a.onerror = function(){ current=null; schedule(1800); };
      a.play().catch(function(){ current=null; schedule(2200); });
    } catch(e){ schedule(2200); }
  }
  new MutationObserver(function(){
    if (sweepActive()){ if (!timer && !current) schedule(1000); }
    else { stop(); }
  }).observe(document.body, {childList:true, subtree:true, attributes:true, attributeFilter:['class','style']});
})();
"""


def _build_voice_head() -> str:
    import json
    folder = ASSETS / "audio"
    uris = []
    for i in range(1, 13):
        p = folder / f"voice_{i:02d}.mp3"
        if p.exists():
            b64 = base64.b64encode(p.read_bytes()).decode("ascii")
            uris.append(f"data:audio/mpeg;base64,{b64}")
    if not uris:
        return ""
    return "<script>\nvar VOICE_LINES=" + json.dumps(uris) + ";\n" + _VOICE_JS + "\n</script>"


VOICE_HEAD = _build_voice_head()


def _bg_video_uri() -> str:
    p = ASSETS / "video" / "bg.mp4"
    if not p.exists():
        return ""
    return "data:video/mp4;base64," + base64.b64encode(p.read_bytes()).decode("ascii")


BG_VIDEO_URI = _bg_video_uri()


def _build_bg_video() -> str:
    """Fixed, dimmed, looping noir video behind everything (if present)."""
    if not BG_VIDEO_URI:
