    )


def _sound_gate_html() -> str:
    """A consent screen shown FIRST: noir smoke background + a question + two
    buttons. YES grants audio (music + all SFX + intro sound); NO runs everything
    silent but never nags. The floating bubble can flip the choice any time."""
    smoke = (
        f'<video class="sg-smoke" autoplay loop muted playsinline preload="auto">'
        f'<source src="{BG_VIDEO_URI}" type="video/mp4"></video>'
        if BG_VIDEO_URI else ""
    )
    return f"""
<div id="sound-gate">
  {smoke}
  <div class="sg-scrim"></div>
  <div class="sg-inner">
    <div class="sg-emblem"></div>
    <div class="sg-kicker">PRECINCT 7 · UX DIVISION</div>
    <h2>This case has a soundtrack.</h2>
    <p>The Inspector works best with the blinds drawn and the volume up —
       rain, jazz, the click of the typewriter.<br>Roll the audio?</p>
    <div class="sg-btns">
      <button type="button" class="sg-yes" onclick="window.UXCGate&&UXCGate.decide(true)">▸ Yes, with sound</button>
      <button type="button" class="sg-no"  onclick="window.UXCGate&&UXCGate.decide(false)">Keep it quiet</button>
    </div>
    <div class="sg-foot">You can flip the sound any time with the ♪ button.</div>
  </div>
</div>
"""


SOUND_GATE_HTML = _sound_gate_html()

# Controller for the consent gate — lives in <head> so it runs natively.
