def _img_data_uri(image: Image.Image, max_side: int | None = None, jpeg: bool = False) -> str:
    """Encode a PIL image as a data URI. Optionally downscale (keeps the DOM light
    on big screenshots) and use JPEG (much smaller than PNG for photos)."""
    img = image.convert("RGB")
    if max_side and max(img.size) > max_side:
        img = img.copy()
        img.thumbnail((max_side, max_side), Image.LANCZOS)
    buf = io.BytesIO()
    if jpeg:
        img.save(buf, format="JPEG", quality=82)
        mime = "image/jpeg"
    else:
        img.save(buf, format="PNG")
        mime = "image/png"
    return f"data:{mime};base64," + base64.b64encode(buf.getvalue()).decode("ascii")


