_asr_model = None
_qwen_model = None
_qwen_tokenizer = None

def _space_transcribe(wav_paths: list, lang_code: str) -> list:
    global _asr_model
    import torch
    if _asr_model is None:
        import nemo.collections.asr as nemo_asr
        _asr_model = nemo_asr.models.ASRModel.from_pretrained(
            "nvidia/nemotron-3.5-asr-streaming-0.6b"
        )
        if torch.cuda.is_available():
            _asr_model = _asr_model.cuda()
    from nemo.collections.asr.models.rnnt_bpe_models_prompt import RNNTPromptTranscribeConfig
    config = RNNTPromptTranscribeConfig(batch_size=len(wav_paths), num_workers=0, use_lhotse=False, target_lang=lang_code)
    results = _asr_model.transcribe(wav_paths, override_config=config, **{lang_code: ""})
    return [r.text if hasattr(r, "text") else str(r) for r in results]

def _space_parse(prompt: str) -> str:
    global _qwen_model, _qwen_tokenizer
    import torch
    if _qwen_model is None:
        from transformers import AutoModelForCausalLM, AutoTokenizer
        model_id = "Qwen/Qwen2.5-1.5B-Instruct"
        _qwen_tokenizer = AutoTokenizer.from_pretrained(model_id)
        _qwen_model = AutoModelForCausalLM.from_pretrained(
            model_id, torch_dtype=torch.float16, device_map="auto"
        )
    text = _qwen_tokenizer.apply_chat_template(
        [{"role": "user", "content": prompt}],
        tokenize=False,
        add_generation_prompt=True,
    )
    inputs = _qwen_tokenizer([text], return_tensors="pt").to(_qwen_model.device)
    with torch.no_grad():
        output_ids = _qwen_model.generate(**inputs, max_new_tokens=512, do_sample=False)
    new_ids = output_ids[0][inputs["input_ids"].shape[1]:]
    return _qwen_tokenizer.decode(new_ids, skip_special_tokens=True)

