def load_catalog_db() -> dict:
    try:
        with sqlite3.connect(DB_PATH) as conn:
            rows = conn.execute("SELECT sku, price, unit, emoji FROM catalog ORDER BY sku").fetchall()
        return {sku: {"price": price, "unit": unit, "emoji": emoji} for sku, price, unit, emoji in rows}
    except Exception:
        return dict(CATALOG)


def load_catalog_df() -> pd.DataFrame:
    catalog = load_catalog_db()
    rows = [
        {"Item": sku, "Price ($)": info["price"], "Unit": info["unit"], "Emoji": info["emoji"]}
        for sku, info in catalog.items()
    ]
    return pd.DataFrame(rows) if rows else pd.DataFrame(columns=["Item", "Price ($)", "Unit", "Emoji"])


def add_catalog_item(sku: str, price: float, unit: str, emoji: str):
    sku = sku.strip().lower()
    if not sku:
        return "Item name is required.", load_catalog_df()
    unit  = unit.strip()  or "count"
    emoji = emoji.strip() or "🌿"
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute(
            "INSERT INTO catalog (sku, price, unit, emoji) VALUES (?, ?, ?, ?)"
            " ON CONFLICT(sku) DO UPDATE SET price=excluded.price, unit=excluded.unit, emoji=excluded.emoji",
            (sku, float(price), unit, emoji),
        )
    log.info("[catalog] upserted %s @ $%.2f", sku, float(price))
    return f"Saved '{sku}'.", load_catalog_df()


def save_catalog(df: pd.DataFrame):
    rows = []
    for _, row in df.iterrows():
        sku = str(row.get("Item", "")).strip().lower()
        if not sku:
            continue
        try:
            price = float(row.get("Price ($)", 0))
        except (ValueError, TypeError):
            continue
        unit  = str(row.get("Unit",  "count")).strip() or "count"
        emoji = str(row.get("Emoji", "🌿")).strip()    or "🌿"
        rows.append((sku, price, unit, emoji))
    with sqlite3.connect(DB_PATH) as conn:
        conn.execute("DELETE FROM catalog")
        conn.executemany(
            "INSERT INTO catalog (sku, price, unit, emoji) VALUES (?, ?, ?, ?)", rows
        )
    log.info("[catalog] saved %d items", len(rows))
    return "Saved.", load_catalog_df()

