def _transcribe_b64(audio_b64: str, audio_format: str, lang_code: str) -> str:
    audio_bytes = base64.b64decode(audio_b64)
    log.info("[transcribe] lang=%s bytes=%d", lang_code, len(audio_bytes))
    if ON_SPACE:
        if _asr_model is None:
            gr.Info("⏳ First order: loading AI models (~90 seconds). Every order after this will take ~5 seconds.", duration=30)
        with tempfile.NamedTemporaryFile(suffix=".webm", delete=False) as f:
            f.write(audio_bytes)
            input_path = f.name
        wav_path = input_path + ".wav"
        try:
            subprocess.run(
                ["ffmpeg", "-y", "-i", input_path, "-ac", "1", "-ar", "16000", wav_path],
                check=True, capture_output=True,
            )
            return _space_transcribe([wav_path], lang_code)[0]
        finally:
            os.unlink(input_path)
            if os.path.exists(wav_path):
                os.unlink(wav_path)
    cls = modal.Cls.from_name("nemotron-asr", "NemotronASR")
    return cls().transcribe.remote(audio_bytes, lang_code)


def _transcribe_parallel(chunks: list[dict], lang_code: str) -> str:
    log.info("[transcribe] %d chunk(s)", len(chunks))
    if ON_SPACE:
        if _asr_model is None:
            gr.Info("⏳ First order: loading AI models (~90 seconds). Every order after this will take ~5 seconds.", duration=30)
        input_paths, wav_paths = [], []
        try:
            for c in chunks:
                audio_bytes = base64.b64decode(c["audio_b64"])
                with tempfile.NamedTemporaryFile(suffix=".webm", delete=False) as f:
                    f.write(audio_bytes)
                    input_path = f.name
                input_paths.append(input_path)
                wav_path = input_path + ".wav"
                wav_paths.append(wav_path)
                subprocess.run(
                    ["ffmpeg", "-y", "-i", input_path, "-ac", "1", "-ar", "16000", wav_path],
                    check=True, capture_output=True,
                )
            results = _space_transcribe(wav_paths, lang_code)
            text = " ".join(r for r in results if r).strip()
            if not text:
                raise RuntimeError("all chunks returned empty transcripts")
            return text
        finally:
            for p in input_paths + wav_paths:
                if os.path.exists(p):
                    os.unlink(p)
    cls = modal.Cls.from_name("nemotron-asr", "NemotronASR")
    obj = cls()
    results = []
    for c in chunks:
        audio_bytes = base64.b64decode(c["audio_b64"])
        results.append(obj.transcribe.remote(audio_bytes, lang_code))
    text = " ".join(r for r in results if r).strip()
    if not text:
        raise RuntimeError("all chunks returned empty transcripts")
    return text


def parse_order(raw_text: str, language_label: str) -> dict:
    catalog_str = "\n".join(
        f"  {sku}: ${info['price']:.2f} per {info['unit']}"
        for sku, info in load_catalog_db().items()
    )
    prompt = f"""You are a produce order parser. The transcript below is in {language_label}.
Extract items from the order and map each to a canonical SKU from the catalog.

Catalog (canonical SKU: price):
{catalog_str}

Rules:
- sku must be exactly one of the catalog names. If an item is not in the catalog, set unit_price to null and line_total to null.
- Resolve self-corrections (e.g. "no, make it six") to the final intended quantity.
- unit is "count", "lb", or "kg" as appropriate.
- native_readback: a short human-readable summary in {language_label} for the vendor to verify.
- Return ONLY valid JSON, no prose, no code fences.

Transcript: "{raw_text}"

JSON:
{{
  "items": [
    {{"sku": "apple", "quantity": 5, "unit": "count", "unit_price": 0.50, "line_total": 2.50}}
  ],
  "order_total": 2.50,
  "native_readback": "5 apples"
}}"""

    if ON_SPACE:
        log.info("[parse] calling _space_parse on CPU")
        content = _space_parse(prompt)
        content = re.sub(r"^```(?:json)?\s*", "", content.strip())
        content = re.sub(r"\s*```$", "", content)
        return json.loads(content.strip())
    log.info("[parse] calling QwenParser via Modal")
    cls = modal.Cls.from_name("qwen-parse", "QwenParser")
    content = cls().parse.remote(prompt)
    content = re.sub(r"^```(?:json)?\s*", "", content.strip())
    content = re.sub(r"\s*```$", "", content)
    return json.loads(content.strip())

