def process_audio(audio_path, language_label):
    if audio_path is None:
        return "", EMPTY_ITEMS_DF, "", None

    lang_code = LANGUAGE_CODES.get(language_label, "en")

    try:
        raw_text = transcribe(audio_path, lang_code)
    except Exception as exc:
        return f"Transcription error: {exc}", EMPTY_ITEMS_DF, "", None

    try:
        parsed = parse_order(raw_text, language_label)
    except Exception as exc:
        return raw_text, EMPTY_ITEMS_DF, f"Parse error: {exc}", None

    rows = []
    for item in parsed.get("items", []):
        price = item.get("unit_price")
        total = item.get("line_total")
        rows.append({
            "Item":  item.get("sku", "?"),
            "Qty":   item.get("quantity", 0),
            "Unit":  item.get("unit", "count"),
            "Price": f"${price:.2f}" if price is not None else "unknown",
            "Total": f"${total:.2f}" if total is not None else "unknown",
        })

    items_df = pd.DataFrame(rows) if rows else EMPTY_ITEMS_DF
    readback = parsed.get("native_readback", "")
    order_total = parsed.get("order_total", 0.0)
    summary = f"{readback}\n\nOrder total: ${order_total:.2f}"

    return raw_text, items_df, summary, parsed


def confirm_sale(parsed, language_label, raw_text):
    if parsed is None:
        return "Nothing to confirm.", None

    lang_code = LANGUAGE_CODES.get(language_label, "en")
    ts = datetime.datetime.utcnow().isoformat()
    items_json = json.dumps(parsed.get("items", []))
    order_total = parsed.get("order_total", 0.0)

    with sqlite3.connect(DB_PATH) as conn:
        conn.execute(
            "INSERT INTO sales (ts, language, raw_text, items_json, order_total) VALUES (?, ?, ?, ?, ?)",
            (ts, lang_code, raw_text, items_json, order_total),
        )

    return f"Sale saved. Total: ${order_total:.2f}", None


