def _build_sales_html(df: pd.DataFrame, page: int, total_pages: int) -> str:
    if df.empty:
        return _SALES_CSS + '<div class="st-wrap"><p class="st-empty">No sales recorded yet.</p></div>'

    _cat = load_catalog_db()
    rows = []
    for _, row in df.iterrows():
        try:
            items = json.loads(row["items_json"])
        except Exception:
            items = []

        try:
            dt = datetime.datetime.fromisoformat(row["ts"])
            ts_str = dt.strftime("%b %d  %H:%M")
        except Exception:
            ts_str = str(row["ts"])[:16]

        lang = LANG_LABELS.get(row["language"], row["language"])
        total = f"${row['order_total']:.2f}"
        n = len(items)
        count_str = f"{n} item{'s' if n != 1 else ''}"

        item_rows_html = ""
        for item in items:
            emoji = _cat.get(item.get("sku", ""), {}).get("emoji", "🌿")
            sku = item.get("sku", "?")
            qty = item.get("quantity", 0)
            up = item.get("unit_price")
            lt = item.get("line_total")
            up_str = f"${up:.2f}" if up is not None else "—"
            lt_str = f"${lt:.2f}" if lt is not None else "—"
            item_rows_html += (
                f"<tr>"
                f"<td>{emoji} {sku}</td>"
                f"<td>{qty}</td>"
                f"<td>{up_str}</td>"
                f"<td>{lt_str}</td>"
                f"</tr>"
            )

        rows.append(
            f'<details class="st-sale">'
            f'<summary class="st-summary">'
            f'<div class="st-summary-inner">'
            f'<span class="st-arrow">&#9654;</span>'
            f'<span class="st-col-time">{ts_str}</span>'
            f'<span class="st-col-lang">{lang}</span>'
            f'<span class="st-col-total">{total}</span>'
            f'<span class="st-col-count">{count_str}</span>'
            f'</div>'
            f'</summary>'
            f'<div class="st-detail">'
            f'<table class="st-items">'
            f'<thead><tr><th>Item</th><th>Qty</th><th>Unit $</th><th>Total</th></tr></thead>'
            f'<tbody>{item_rows_html}</tbody>'
            f'</table>'
            f'</div>'
            f'</details>'
        )

    page_info = f'<p class="st-page-label">Page {page + 1} of {total_pages}</p>' if total_pages > 1 else ""
    header = (
        '<div class="st-head">'
        '<span></span>'
        '<span>Time</span>'
        '<span>Language</span>'
        '<span>Total</span>'
        '<span>Items</span>'
        '</div>'
    )
    rows_html = "".join(rows)
    return _SALES_CSS + f'<div class="st-wrap">{header}{rows_html}{page_info}</div>'


def _load_sales_df() -> pd.DataFrame:
    try:
        with sqlite3.connect(DB_PATH) as conn:
            return pd.read_sql_query("SELECT * FROM sales ORDER BY ts DESC", conn)
    except Exception as exc:
        log.warning("[dashboard] failed to load sales: %s", exc)
        return pd.DataFrame()


def _build_charts(df: pd.DataFrame):
    empty_sku = pd.DataFrame({"sku": pd.Series(dtype=str), "quantity": pd.Series(dtype=float)})
    empty_rev = pd.DataFrame({"date": pd.Series(dtype=str), "revenue": pd.Series(dtype=float)})
    if df.empty:
        return empty_sku, empty_rev
    sku_rows = []
    for _, row in df.iterrows():
        try:
            for item in json.loads(row["items_json"]):
                sku_rows.append({"sku": item["sku"], "quantity": item["quantity"]})
        except Exception as exc:
            log.warning("[dashboard] skipping malformed row id=%s: %s", row.get("id"), exc)
    sku_df = pd.DataFrame(sku_rows) if sku_rows else empty_sku
    if not sku_df.empty:
        sku_df = sku_df.groupby("sku", as_index=False)["quantity"].sum()
    df = df.copy()
    df["date"] = df["ts"].str[:10]
    rev_df = df.groupby("date", as_index=False)["order_total"].sum()
    rev_df.columns = ["date", "revenue"]
    return sku_df, rev_df


def load_dashboard(page: int = 0):
    df = _load_sales_df()
    sku_df, rev_df = _build_charts(df)
    total = len(df)
    total_pages = max(1, math.ceil(total / _PER_PAGE))
    page = max(0, min(page, total_pages - 1))
    page_df = df.iloc[page * _PER_PAGE: (page + 1) * _PER_PAGE] if not df.empty else df
    return _build_sales_html(page_df, page, total_pages), sku_df, rev_df, page


def go_prev(page: int):
    return load_dashboard(max(0, page - 1))


def go_next(page: int):
    return load_dashboard(page + 1)


